  const dst = ac.createMediaStreamDestination();
  osc.connect(g).connect(dst); osc.start();
  navigator.mediaDevices.getUserMedia = async () => dst.stream;

  // 2) tap every frame the app sends to its playback worklet
  window.__frames = { count: 0, samples: 0, energy: 0, ctxRate: null };
  const OrigNode = window.AudioWorkletNode;
  window.AudioWorkletNode = function(context, name, opts) {
    const node = new OrigNode(context, name, opts);
    if (name === 'moshi-processor') {
      window.__frames.ctxRate = context.sampleRate;
      const origPost = node.port.postMessage.bind(node.port);
      node.port.postMessage = (msg, xfer) => {
        const f = msg && msg.frame;
        if (f && f.length) {
          window.__frames.count++;
          window.__frames.samples += f.length;
          let e = 0; for (let i = 0; i < f.length; i++) e += f[i]*f[i];
          window.__frames.energy += e;
        }
        return origPost(msg, xfer);
      };
    }
    return node;
  };
})();

