  const ac = new (window.AudioContext || window.webkitAudioContext)();
  const osc = ac.createOscillator(); const g = ac.createGain();
  g.gain.value = 0.0001;
  const dst = ac.createMediaStreamDestination();
  osc.connect(g).connect(dst); osc.start();
  navigator.mediaDevices.getUserMedia = async () => dst.stream;

  window.__cap = { opus: [], frames: [], ctxRate: null };

  // tap incoming server audio (0x01) on the WebSocket
  const OrigWS = window.WebSocket;
  window.WebSocket = function(...a) {
    const ws = new OrigWS(...a);
    ws.addEventListener('message', (ev) => {
      const d = ev.data;
      if (d instanceof ArrayBuffer) {
        const u = new Uint8Array(d);
        if (u.length && u[0] === 1) window.__cap.opus.push(Array.from(u.subarray(1)));
      }
    });
    return ws;
  };
  window.WebSocket.prototype = OrigWS.prototype;
  Object.assign(window.WebSocket, OrigWS);

  // tap decoded frames to the playback worklet
  const OrigNode = window.AudioWorkletNode;
  window.AudioWorkletNode = function(context, name, opts) {
    const node = new OrigNode(context, name, opts);
    if (name === 'moshi-processor') {
      window.__cap.ctxRate = context.sampleRate;
      const op = node.port.postMessage.bind(node.port);
      node.port.postMessage = (m, x) => {
        if (m && m.frame && m.frame.length) window.__cap.frames.push(Array.from(m.frame));
        return op(m, x);
      };
    }
    return node;
  };
})();

