from __future__ import annotations

import re

from aiohttp import web

WORKLET_CACHE_BUSTER = "personaplex-buffer-v2"


def patch_moshi_processor_js(source: str) -> str:
    replacements = {
        "this.initialBufferSamples=1*l": "this.initialBufferSamples=4*l",
        "this.partialBufferSamples=i(10),this.maxBufferSamples=i(10),this.partialBufferIncrement=i(5),this.maxPartialWithIncrements=i(80),this.maxBufferSamplesIncrement=i(5),this.maxMaxBufferWithIncrements=i(80)": (
            "this.partialBufferSamples=i(120),this.maxBufferSamples=i(480),"
            "this.partialBufferIncrement=i(20),this.maxPartialWithIncrements=i(240),"
            "this.maxBufferSamplesIncrement=i(40),this.maxMaxBufferWithIncrements=i(1200)"
        ),
        "this.partialBufferSamples=i(10),this.maxBufferSamples=i(10)}totalMaxBufferSamples": (
            "this.partialBufferSamples=i(120),this.maxBufferSamples=i(480)}totalMaxBufferSamples"
        ),
    }
    patched = source
    for old, new in replacements.items():
        patched = patched.replace(old, new)
    return patched


def patch_main_bundle_js(source: str) -> str:
    return re.sub(
        r'const moshiProcessorUrl = "([^"]*audio-processor-[^"]+\.js)";',
        rf'const moshiProcessorUrl = "\1?{WORKLET_CACHE_BUSTER}";',
        source,
        count=1,
    )


def javascript_response(source: str) -> web.Response:
