"""TTS stage for the cascade: stream LM text -> speech with Voxtral TTS (mlx-audio).

``clause_chunks`` segments the LM's token stream at sentence/clause boundaries so
the TTS can start synthesizing the first clause while the LM is still producing
the rest — the key to a low end-to-end time-to-first-audio.
"""

from __future__ import annotations

import re
from typing import Iterator

# Flush a chunk to TTS when we reach a sentence end, or a clause break once the
# buffer is long enough to be worth speaking (keeps prosody natural, latency low).
_SENTENCE_END = re.compile(r"[.!?](?=\s|$)")
_CLAUSE_BREAK = re.compile(r"[,;:](?=\s)")
_MIN_CLAUSE_CHARS = 30


def clause_chunks(text_stream: Iterator[str]) -> Iterator[str]:
    """Yield speakable chunks from a stream of text deltas."""
    buf = ""
    for delta in text_stream:
        buf += delta
        while True:
            cut = None
            m = _SENTENCE_END.search(buf)
            if m:
                cut = m.end()
            elif len(buf) >= _MIN_CLAUSE_CHARS:
                c = _CLAUSE_BREAK.search(buf)
                if c:
                    cut = c.end()
            if cut is None:
                break
            chunk = buf[:cut].strip()
            buf = buf[cut:]
            if chunk:
                yield chunk
    tail = buf.strip()
    if tail:
        yield tail


class VoxtralTTS:
    """Thin wrapper over mlx-audio's Voxtral TTS for the cascade."""

    def __init__(
        self,
        model_id: str = "mlx-community/Voxtral-4B-TTS-2603-mlx-6bit",
        voice: str = "cheerful_female",
        temperature: float = 0.5,
    ):
        from mlx_audio.tts.utils import load  # lazy

        self.model = load(model_id)
        self.voice = voice
        self.temperature = temperature

    @property
    def sample_rate(self) -> int:
        return self.model.sample_rate

    def synth(self, text: str):
        import numpy as np

        chunks = []
        for r in self.model.generate(
            text=text, voice=self.voice, temperature=self.temperature, stream=False
        ):
            chunks.append(np.asarray(r.audio).reshape(-1))
        return np.concatenate(chunks) if chunks else np.zeros(0, dtype="float32")

