class OpenAICompatLM:
    """Chat completion via any OpenAI-compatible /v1/chat/completions endpoint.

    Covers a local llama.cpp ``llama-server`` (GGUF + MTP speculative decoding),
    vLLM, or any hosted OpenAI-style API — the difference is just ``base_url``.
    Uses httpx + SSE parsing so there is no hard dependency on the openai SDK.
    """

    def __init__(self, cfg: LMConfig):
        self.cfg = cfg
        self._url = cfg.base_url.rstrip("/") + "/chat/completions"

    def stream(self, messages: list[dict]) -> Iterator[str]:
        import json

        import httpx

        headers = {"Content-Type": "application/json"}
        if self.cfg.api_key:
            headers["Authorization"] = f"Bearer {self.cfg.api_key}"
        payload = {
            "model": self.cfg.model,
            "messages": messages,
            "max_tokens": self.cfg.max_tokens,
            "temperature": self.cfg.temperature,
            "stream": True,
        }
        if self.cfg.stop:
            payload["stop"] = self.cfg.stop
        with httpx.Client(timeout=httpx.Timeout(60.0, connect=10.0)) as client:
            with client.stream("POST", self._url, json=payload, headers=headers) as r:
                r.raise_for_status()
                for line in r.iter_lines():
                    if not line or not line.startswith("data:"):
                        continue
                    data = line[len("data:") :].strip()
                    if data == "[DONE]":
                        break
                    obj = json.loads(data)
                    choices = obj.get("choices") or []
                    if not choices:
                        continue
                    text = (choices[0].get("delta") or {}).get("content")
                    if text:
                        yield text


