def stream(self, messages: list[dict]) -> Iterator[str]:
    # `chat_template_kwargs.enable_thinking` toggles reasoning models'
    # chain-of-thought. Harmlessly ignored by models without the switch.
    stream = self.client.chat.completions.create(
        model=self.cfg.model,
        messages=messages,
        max_tokens=self.cfg.max_tokens,
        temperature=self.cfg.temperature,
        stop=self.cfg.stop or None,
        stream=True,
        extra_body={
            "chat_template_kwargs": {"enable_thinking": self.cfg.enable_thinking}
        },
    )
    for chunk in stream:
        # Final chunks may carry usage only (empty choices) -> guard.
        choices = getattr(chunk, "choices", None)
        if not choices:
            continue
        delta = choices[0].delta
        # Only the spoken answer (`content`) goes to TTS; never the `reasoning`.
        text = getattr(delta, "content", None)
        if text:
            yield text

