1	// Mints a short-lived OpenAI realtime ephemeral key (client secret) server-side
2	// so the browser can open a WebRTC session WITHOUT ever seeing OPENAI_API_KEY.
3	//
4	// Flow: client POSTs here → we call OpenAI with the secret key → return the
5	// ephemeral key JSON. The browser then negotiates WebRTC directly with OpenAI:
6	//   POST https://api.openai.com/v1/realtime/calls
7	//     Authorization: Bearer <ephemeral key>, Content-Type: application/sdp
8	// Full per-persona config is applied client-side via `session.update`, so the
9	// mint body stays minimal here.
10	//
11	// Dev only: OPENAI_API_KEY is provided via fnox (`fnox exec -- bun run dev`).
12	
13	export const runtime = "nodejs";
14	// Never cache a freshly-minted secret.
15	export const dynamic = "force-dynamic";
16	
17	const CLIENT_SECRETS_URL = "https://api.openai.com/v1/realtime/client_secrets";
18	const MODEL = "gpt-realtime-2";
19	
20	export async function POST(): Promise<Response> {
21	  const apiKey = process.env.OPENAI_API_KEY;
22	  if (!apiKey) {
23	    // Do not echo any key material; just say it's unset.
24	    return Response.json(
25	      { error: "OPENAI_API_KEY is not set on the server (provide it via fnox)." },
26	      { status: 500 },
27	    );
28	  }
29	
30	  let upstream: Response;
31	  try {
32	    upstream = await fetch(CLIENT_SECRETS_URL, {
33	      method: "POST",
34	      headers: {
35	        Authorization: `Bearer ${apiKey}`,
36	        "Content-Type": "application/json",
37	      },
38	      body: JSON.stringify({ session: { type: "realtime", model: MODEL } }),
39	    });
40	  } catch (err) {
41	    return Response.json(
42	      { error: `Failed to reach OpenAI: ${err instanceof Error ? err.message : "network error"}` },
43	      { status: 502 },
44	    );
45	  }
46	
47	  const text = await upstream.text();
48	  if (!upstream.ok) {
49	    // Surface OpenAI's status + body (it doesn't contain our key) for debugging.
50	    return Response.json(
51	      { error: "OpenAI client_secrets request failed", status: upstream.status, detail: text },
52	      { status: 502 },
53	    );
54	  }
55	
56	  // Pass the key JSON straight through; the client extracts the value defensively.
57	  return new Response(text, {
58	    status: 200,
59	    headers: { "Content-Type": "application/json", "Cache-Control": "no-store" },
60	  });
61	}
