10	const SCRIPT_TURNS: SessionTurn[] = TRANSCRIPT_SCRIPT.map((t, i) => ({
11	  id: `s${i}`,
12	  who: t.who,
13	  text: t.text,
14	}));
15	
16	const LAST = TRANSCRIPT_SCRIPT.length - 1;
