35	/**
36	 * Unified realtime session. `provider.engine` selects the engine:
37	 *   - undefined → the design's mock lifecycle (timers + TRANSCRIPT_SCRIPT)
38	 *   - "elevenlabs" → real conversation via `@elevenlabs/react`
39	 *   - "xai" → real Grok voice via a direct WebSocket (useXaiSession)
40	 *   - "openai" → real gpt-realtime-2 voice via WebRTC (useOpenaiSession)
41	 * All expose the same `SessionApi` so the UI is provider-agnostic.
42	 *
43	 * `useXaiSession` and `useOpenaiSession` share one interface, so the dispatcher
44	 * picks whichever is active as `custom` and routes every control through it.
45	 *
46	 * All real-engine hooks (`useConversation`, `useXaiSession`, `useOpenaiSession`)
47	 * are called unconditionally (rules of hooks) and stay inert until their engine
48	 * is selected and started.
49	 */
50	export function useRealtimeSession({
51	  provider,
52	  persona,
53	}: {
54	  provider: Provider;
55	  persona?: Persona;
56	}): SessionApi {
57	  const engine = provider.engine;
58	  const isReal = !!engine;
59	
60	  const [callState, setCallState] = useState<CallState>(isReal ? "idle" : "listening");
61	  const [turns, setTurns] = useState<SessionTurn[]>(isReal ? [] : SCRIPT_TURNS);
62	  const [caption, setCaption] = useState<string>(
63	    isReal ? "press CALL to begin" : mockCaption("listening"),
64	  );
65	  const [muted, setMuted] = useState(false);
66	  const [elapsed, setElapsed] = useState(0);
67	
68	  const stateRef = useRef(callState);
69	  stateRef.current = callState;
70	  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
71	  const clearTimers = () => {
72	    timers.current.forEach(clearTimeout);
73	    timers.current = [];
74	  };
75	
76	  // ── ElevenLabs real conversation ──────────────────────────────────────────
77	  const realPhase = useRef<"idle" | "active" | "ended">("idle");
78	  const conversation = useConversation({
79	    micMuted: muted,
80	    onMessage: (msg: { source?: string; message?: string }) => {
81	      const who = msg.source === "user" ? "user" : "agent";
82	      const text = msg.message ?? "";
83	      if (!text) return;
84	      setTurns((prev) => [...prev, { id: `r${prev.length}`, who, text }]);
85	      setCaption(text);
86	    },
87	    onError: () => {
88	      realPhase.current = "ended";
89	      setCallState("ended");
90	      setCaption("— connection error —");
91	    },
92	  });
93	
94	  const { status, mode, isSpeaking, startSession, endSession } = conversation;
95	
96	  // ── Custom real engines (own WebSocket / WebRTC, shared interface) ─────────
97	  const xai = useXaiSession(engine === "xai", persona);
98	  const openai = useOpenaiSession(engine === "openai", persona);
99	  // Whichever custom engine is active owns the session; null ⇒ ElevenLabs/mock.
100	  const custom = engine === "xai" ? xai : engine === "openai" ? openai : null;
101	
102	  // The active call state comes from whichever engine owns the session.
103	  const activeCallState: CallState = custom ? custom.callState : callState;
104	
105	  // Derive real CallState from the conversation status/mode (ElevenLabs only).
106	  useEffect(() => {
107	    if (engine !== "elevenlabs" || realPhase.current === "idle") return;
108	    if (realPhase.current === "ended") {
109	      setCallState("ended");
110	      return;
111	    }
112	    if (status === "connecting") setCallState("connecting");
113	    else if (status === "error") setCallState("ended");
114	    else if (status === "disconnected") setCallState("ended");
115	    else if (status === "connected") {
116	      setCallState(mode === "speaking" || isSpeaking ? "speaking" : "listening");
117	      setCaption((c) => (c === "establishing session…" ? "listening…" : c));
118	    }
119	  }, [engine, status, mode, isSpeaking]);
120	
121	  // ── Mock lifecycle ──────────────────────────────────────────────────────────
122	  // First-load drift: listening → speaking after 5s (matches the prototype).
123	  useEffect(() => {
124	    if (isReal) return;
125	    if (callState !== "listening") return;
126	    const t = setTimeout(() => setCallState("speaking"), 5000);
127	    return () => clearTimeout(t);
128	    // eslint-disable-next-line react-hooks/exhaustive-deps
129	  }, [isReal]);
130	
131	  // Caption sync for the mock engine.
132	  useEffect(() => {
133	    if (isReal) return;
134	    setCaption(mockCaption(callState));
135	  }, [isReal, callState]);
136	
137	  // Elapsed ticker (all engines) — keyed off whichever engine owns the call.
138	  useEffect(() => {
139	    if (activeCallState === "idle" || activeCallState === "ended") {
140	      setElapsed(0);
141	      return;
142	    }
143	    const t = setInterval(() => setElapsed((e) => e + 1), 1000);
144	    return () => clearInterval(t);
145	  }, [activeCallState]);
146	
147	  // Push mute into the active real engine. ElevenLabs only accepts setMuted once
148	  // connected (it throws "No active conversation" before startSession()); xAI
149	  // gates its own mic send, so it's always safe.
150	  useEffect(() => {
151	    if (engine === "elevenlabs" && status === "connected") conversation.setMuted(muted);
152	    else if (custom) custom.setMuted(muted);
153	    // eslint-disable-next-line react-hooks/exhaustive-deps
154	  }, [muted, engine, status]);
155	
156	  // Reset to the active engine's initial state when the engine changes. End any
157	  // live ElevenLabs session we're navigating away from (xAI tears itself down
158	  // via its own `active` effect).
159	  useEffect(() => {
160	    clearTimers();
161	    try {
162	      if (realPhase.current === "active") endSession();
163	    } catch {
164	      // no active ElevenLabs session
165	    }
166	    realPhase.current = "idle";
167	    if (isReal) {
168	      setCallState("idle");
169	      setTurns([]);
170	      setCaption("press CALL to begin");
171	    } else {
172	      setCallState("listening");
173	      setTurns(SCRIPT_TURNS);
174	      setCaption(mockCaption("listening"));
175	    }
176	    // eslint-disable-next-line react-hooks/exhaustive-deps
177	  }, [engine]);
178	
179	  useEffect(() => () => clearTimers(), []);
180	
181	  // ── Controls ────────────────────────────────────────────────────────────────
182	  const start = useCallback(() => {
183	    if (custom) {
184	      custom.start();
185	      return;
186	    }
187	    if (engine === "elevenlabs") {
188	      if (callState === "idle" || callState === "ended") {
189	        const agentId = process.env.NEXT_PUBLIC_ELEVENLABS_AGENT_ID;
190	        if (!agentId) {
