213	    } else {
214	      setCallState("ended");
215	    }
216	  }, [engine, custom, callState, startSession, endSession]);
217	
218	  const hangup = useCallback(() => {
219	    if (custom) {
220	      custom.stop();
221	      return;
222	    }
223	    if (engine === "elevenlabs") {
224	      realPhase.current = "ended";
225	      endSession();
226	    } else {
227	      clearTimers();
228	    }
229	    setCallState("ended");
230	  }, [engine, custom, endSession]);
231	
232	  const interrupt = useCallback(() => {
233	    if (custom) {
234	      custom.interrupt();
235	      return;
236	    }
237	    if (stateRef.current !== "speaking") return;
238	    if (engine === "elevenlabs") {
