241	      return;
242	    }
243	    clearTimers();
244	    setCallState("interrupted");
245	    timers.current.push(setTimeout(() => setCallState("listening"), 900));
246	  }, [engine, custom, conversation]);
247	
248	  const toggleMute = useCallback(() => setMuted((m) => !m), []);
249	
250	  // ── Volumes for the orb ───────────────────────────────────────────────────
251	  const getInputVolume = useCallback(() => {
252	    if (engine === "elevenlabs") {
253	      // Throws before startSession(); fall back to silence until connected.
254	      try {
255	        return conversation.getInputVolume();
256	      } catch {
