258	      }
259	    }
260	    const s = stateRef.current;
261	    if (s === "listening" || s === "interrupted") {
262	      return 0.25 + 0.4 * Math.abs(Math.sin(performance.now() / 180));
263	    }
264	    return 0.04;
265	  }, [engine, conversation]);
266	
267	  const getOutputVolume = useCallback(() => {
