279	    return 0.04;
280	  }, [engine, conversation]);
281	
282	  return useMemo<SessionApi>(
283	    () => ({
284	      callState: activeCallState,
285	      turns: custom ? custom.turns : turns,
286	      caption: custom ? custom.caption : caption,
287	      muted,
288	      elapsed,
289	      isReal,
290	      toggleMute,
291	      start,
292	      hangup,
293	      interrupt,
294	      getInputVolume: custom ? custom.getInputVolume : getInputVolume,
295	      getOutputVolume: custom ? custom.getOutputVolume : getOutputVolume,
