// Server-side LM stage for the STT → LM → TTS cascade engine.
//
// Streams an OpenAI-compatible chat completion from one of two backends, chosen
// per request so the cascade can swap LMs without the browser ever seeing a key:
//   - "hf"      → Hugging Face Inference router (any served model, e.g. gemma-4-31B-it)
//   - "mistral" → Mistral API (e.g. mistral-small-latest)
// The upstream SSE body is piped straight back to the client, which reads the
// `data: {...}` deltas. Reasoning models stream chain-of-thought in a separate
// field and emit no spoken `content` until thinking ends, so we send
// `chat_template_kwargs.enable_thinking:false` by default (ignored otherwise).
//
// Dev only: HF_TOKEN / MISTRAL_API_KEY are provided via fnox (`fnox exec -- bun run dev`).

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type Backend = "hf" | "mistral";

const UPSTREAM: Record<Backend, { url: string; envKey: string }> = {
  hf: {
    url: "https://router.huggingface.co/v1/chat/completions",
    envKey: "HF_TOKEN",
  },
  mistral: {
    url: "https://api.mistral.ai/v1/chat/completions",
    envKey: "MISTRAL_API_KEY",
  },
};

interface LlmRequest {
  backend?: Backend;
  model?: string;
  messages?: Array<{ role: string; content: string }>;
  maxTokens?: number;
  temperature?: number;
  enableThinking?: boolean;
}

export async function POST(req: Request): Promise<Response> {
  let body: LlmRequest;
  try {
    body = (await req.json()) as LlmRequest;
  } catch {
    return Response.json({ error: "Invalid JSON body." }, { status: 400 });
  }

  const backend: Backend = body.backend === "mistral" ? "mistral" : "hf";
  const { url, envKey } = UPSTREAM[backend];
  const apiKey = REDACTED;
  if (!apiKey) {
    return Response.json(
      { error: `${envKey} is not set on the server (provide it via fnox).` },
      { status: 500 },
    );
  }
  if (!body.model || !Array.isArray(body.messages) || body.messages.length === 0) {
    return Response.json({ error: "model and messages are required." }, { status: 400 });
  }

  const upstreamBody: Record<string, unknown> = {
    model: body.model,
    messages: body.messages,
    stream: true,
    max_tokens: body.maxTokens ?? 256,
    temperature: body.temperature ?? 0.7,
    // Toggle reasoning models' chain-of-thought; harmlessly ignored by others.
    chat_template_kwargs: { enable_thinking: body.enableThinking ?? false },
  };

  let upstream: Response;
  try {
    upstream = await fetch(url, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
        Accept: "text/event-stream",
      },
      body: JSON.stringify(upstreamBody),
    });
  } catch (err) {
    return Response.json(
      { error: `Failed to reach ${backend}: ${err instanceof Error ? err.message : "network error"}` },
      { status: 502 },
    );
  }

  if (!upstream.ok || !upstream.body) {
    const detail = await upstream.text().catch(() => "");
    return Response.json(
      { error: `${backend} chat completion failed`, status: upstream.status, detail },
      { status: 502 },
    );
  }

  // Pipe the upstream SSE straight to the client.
  return new Response(upstream.body, {
    status: 200,
    headers: {
      "Content-Type": "text/event-stream; charset=utf-8",
      "Cache-Control": "no-store",
      Connection: "keep-alive",
    },
  });
}

// Cascade agent configuration — per-persona settings for the STT → LM → TTS
// engine. Mirrors `xai-agent.ts`: shared defaults in BASE, each persona overrides
// only what personalizes it (LM model + system prompt + opening line + voice).
//
// The LM runs server-side via /api/llm (HF Inference router or Mistral); only the
// declarative config lives here. Secrets (HF_TOKEN, MISTRAL_API_KEY) stay in fnox.
//
// MVP STT/TTS are browser-native (Web Speech + speechSynthesis); `ttsVoice` is a
// voice hint that becomes a Mistral `voice_id` when the Mistral legs land.

export type LmBackend = "hf" | "mistral";

export interface CascadeAgentConfig {
  /** Which /api/llm backend serves this persona. */
  lmBackend: LmBackend;
  /** Model id: an HF-router repo (e.g. google/gemma-4-31B-it) or a Mistral model. */
  lmModel: string;
  /** Spoken-style system prompt. */
  instructions: string;
  /** Prompt that elicits the opening line (sent as the first user turn). */
  firstMessage: string;
  /** Voice hint: a browser speechSynthesis voice substring now; Mistral voice_id later. */
  ttsVoice: string;
  temperature: number;
  maxTokens: number;
}

// Spoken-audio guardrails shared by every persona (reply is read aloud by TTS).
const SHARED = `You are a voice agent inside Tsubaki, a realtime voice interface.
You are speaking to the user live over audio, so keep every reply short, natural, and conversational.
Never use markdown, bullet lists, headings, code blocks, or emoji — your words are spoken aloud.
If you don't know something, say so briefly.`;

const BASE: Pick<CascadeAgentConfig, "lmBackend" | "lmModel" | "temperature" | "maxTokens"> = {
  lmBackend: "hf",
  lmModel: "google/gemma-4-31B-it",
  temperature: 0.7,
  maxTokens: 200,
};

type PersonaAgent = Pick<CascadeAgentConfig, "instructions" | "firstMessage" | "ttsVoice"> &
  Partial<Pick<CascadeAgentConfig, "lmBackend" | "lmModel" | "temperature" | "maxTokens">>;

// Keyed by `Persona.id` from lib/data.ts. Edit freely — the prompt document per persona.
const PERSONA_AGENTS: Record<string, PersonaAgent> = {
  aria: {
    ttsVoice: "Samantha",
    firstMessage: "Greet me warmly in one short sentence as Aria, then ask what I'd like help with.",
    instructions: `${SHARED}

You are Aria: a warm, calm, measured guide tuned for onboarding and supportive conversations.
Reassure before you instruct. Never rush the user.`,
  },
  onyx: {
    ttsVoice: "Daniel",
    firstMessage: "Greet me in one terse sentence as Onyx — dry and unhurried.",
    instructions: `${SHARED}

You are Onyx: a gravelly, authoritative baritone. Laconic — say the most with the fewest words.
Read numbers, dates, and names precisely. Prefer a single well-chosen sentence.`,
  },
  sage: {
    ttsVoice: "Alex",
    firstMessage: "Greet me in one crisp, neutral sentence as Sage and ask how you can help.",
    instructions: `${SHARED}

You are Sage: the professional default. Clear, neutral, efficient. No filler. Answer directly and move on.`,
  },
  nova: {
    ttsVoice: "Karen",
    firstMessage: "Open with an upbeat one-line hello as Nova and invite me to dive in.",
    instructions: `${SHARED}

You are Nova: a bright, high-energy presenter. Upbeat without being exhausting. Keep momentum, stay concise.`,
  },
  echo: {
    ttsVoice: "Moira",
    firstMessage: "Greet me softly and intimately in one short line as Echo.",
    instructions: `${SHARED}

You are Echo: a soft, intimate tenor. Keep your voice low and close, unhurried and gentle. Short, calm sentences.`,
  },
  cipher: {
    ttsVoice: "Tessa",
    firstMessage:
      "Open like the first sentence of a mystery novel — one evocative line — then ask what brought me here.",
    instructions: `${SHARED}

You are Cipher: a mystery-novel narrator. Measured pacing, concrete imagery, short sentences that breathe.
Never purple, never a monologue — this is still a real conversation.`,
  },
};

const DEFAULT_PERSONA_AGENT: PersonaAgent = {
  ttsVoice: "Samantha",
  firstMessage: "Greet me briefly and ask how you can help.",
  instructions: `${SHARED}

You are a warm, engaging, empathetic realtime voice assistant.`,
};

/** Merge the selected persona over the shared BASE config. */
export function resolveCascadeAgent(personaId?: string): CascadeAgentConfig {
  const persona = (personaId && PERSONA_AGENTS[personaId]) || DEFAULT_PERSONA_AGENT;
  return { ...BASE, ...persona };
}

"use client";

// Cascade voice engine: STT → LM → TTS, turn-based, as a SessionApi-compatible
// custom engine (same shape as useXaiSession). MVP legs are browser-native so it
// works today with only a server-side HF/Mistral key for the LM:
//   - STT  → Web Speech API (webkitSpeechRecognition), streaming transcripts
//   - LM   → /api/llm (HF Inference router or Mistral), streamed clauses
//   - TTS  → speechSynthesis, speaking each clause as the LM produces it
// The Mistral realtime-STT + TTS legs replace the two browser pieces later; the
// LM and turn machine stay the same.

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { Persona } from "@/lib/data";
import { resolveCascadeAgent } from "./cascade-agent";
import type { CallState, SessionTurn } from "./types";

export interface CascadeSession {
  callState: CallState;
  turns: SessionTurn[];
  caption: string;
  start: () => void;
  stop: () => void;
  interrupt: () => void;
  setMuted: (muted: boolean) => void;
  getInputVolume: () => number;
  getOutputVolume: () => number;
}

// ── Minimal Web Speech typings (not in the standard DOM lib) ──────────────────
interface SpeechRecognitionAlternative {
  transcript: string;
}
interface SpeechRecognitionResult {
  0: SpeechRecognitionAlternative;
  isFinal: boolean;
}
interface SpeechRecognitionEvent {
  resultIndex: number;
  results: { length: number; [i: number]: SpeechRecognitionResult };
}
interface SpeechRecognitionLike {
  lang: string;
  continuous: boolean;
  interimResults: boolean;
  start: () => void;
  stop: () => void;
  abort: () => void;
  onresult: ((e: SpeechRecognitionEvent) => void) | null;
  onend: (() => void) | null;
  onerror: ((e: { error?: string }) => void) | null;
}
type SpeechRecognitionCtor = new () => SpeechRecognitionLike;

function getRecognitionCtor(): SpeechRecognitionCtor | null {
  if (typeof window === "undefined") return null;
  const w = window as unknown as {
    SpeechRecognition?: SpeechRecognitionCtor;
    webkitSpeechRecognition?: SpeechRecognitionCtor;
  };
  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
}

// Segment a streamed token buffer into speakable clauses (sentence end, or a
// clause break once long enough) so TTS starts on the first clause.
const SENTENCE_END = /[.!?](?=\s|$)/;
const CLAUSE_BREAK = /[,;:](?=\s)/;
const MIN_CLAUSE = 30;

function nextClause(buf: string): [string, string] | null {
  const end = buf.match(SENTENCE_END);
  if (end && end.index != null) {
    const cut = end.index + 1;
    return [buf.slice(0, cut).trim(), buf.slice(cut)];
  }
  if (buf.length >= MIN_CLAUSE) {
    const c = buf.match(CLAUSE_BREAK);
    if (c && c.index != null) {
      const cut = c.index + 1;
      return [buf.slice(0, cut).trim(), buf.slice(cut)];
    }
  }
  return null;
}

export function useCascadeSession(active: boolean, persona?: Persona): CascadeSession {
  const [callState, setCallState] = useState<CallState>("idle");
  const [turns, setTurns] = useState<SessionTurn[]>([]);
  const [caption, setCaption] = useState("press CALL to begin");

  const agent = useMemo(() => resolveCascadeAgent(persona?.id), [persona?.id]);
  const agentRef = useRef(agent);
  agentRef.current = agent;

  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
  const messagesRef = useRef<Array<{ role: string; content: string }>>([]);
  const mutedRef = useRef(false);
  const speakingRef = useRef(false);
  const abortRef = useRef<AbortController | null>(null);
  const liveTurnId = useRef<string | null>(null);

  const stateRef = useRef<CallState>("idle");
  const setState = useCallback((s: CallState) => {
    stateRef.current = s;
    setCallState(s);
  }, []);

  const stopRecognition = useCallback(() => {
    const rec = recognitionRef.current;
    if (rec) {
      rec.onend = null;
      try {
        rec.abort();
      } catch {
        // already stopped
      }
    }
  }, []);

  const startListening = useCallback(() => {
    const Ctor = getRecognitionCtor();
    if (!Ctor) {
      setCaption("— speech recognition unavailable (use Chrome) —");
      return;
    }
    const rec = new Ctor();
    rec.lang = "en-US";
    rec.continuous = true;
    rec.interimResults = true;
    rec.onresult = (e) => {
      if (speakingRef.current || mutedRef.current) return;
      let interim = "";
      let finalText = "";
      for (let i = e.resultIndex; i < e.results.length; i++) {
        const r = e.results[i];
        if (r.isFinal) finalText += r[0].transcript;
        else interim += r[0].transcript;
      }
      if (interim) setCaption(interim);
      if (finalText.trim()) onUserTurn(finalText.trim());
    };
    rec.onerror = () => {};
    // Chrome stops recognition on silence; restart it while we're still listening.
    rec.onend = () => {
      if (stateRef.current === "listening" && !speakingRef.current) {
        try {
          rec.start();
        } catch {
          // start() throws if already running; ignore
        }
      }
    };
    recognitionRef.current = rec;
    try {
      rec.start();
    } catch {
      // ignore double-start
    }
    setState("listening");
  }, [setState]);

  // Speak one clause; resolves when finished (or immediately if no TTS).
  const speakClause = useCallback((text: string): Promise<void> => {
    return new Promise((resolve) => {
      if (typeof window === "undefined" || !window.speechSynthesis) {
        resolve();
        return;
      }
      const u = new SpeechSynthesisUtterance(text);
      const want = agentRef.current.ttsVoice;
      const voices = window.speechSynthesis.getVoices();
      const match = voices.find((v) => v.name.includes(want));
      if (match) u.voice = match;
      u.onend = () => resolve();
      u.onerror = () => resolve();
      window.speechSynthesis.speak(u);
    });
  }, []);

  // Run one assistant turn: stream the LM reply and speak it clause by clause.
  const onUserTurn = useCallback(
    async (userText: string) => {
      stopRecognition();
      speakingRef.current = true;
      setTurns((prev) => [...prev, { id: `u${prev.length}`, who: "user", text: userText }]);
      messagesRef.current.push({ role: "user", content: userText });
      setState("speaking");

      const a = agentRef.current;
      const agentTurnId = `a${Date.now()}`;
      liveTurnId.current = agentTurnId;
      setTurns((prev) => [...prev, { id: agentTurnId, who: "agent", text: "", live: true }]);

      abortRef.current?.abort();
      const ac = new AbortController();
      abortRef.current = ac;

      let buf = "";
      let full = "";
      const speakQueue: Promise<void> = Promise.resolve();
      let chain = speakQueue;

      const enqueue = (clause: string) => {
        chain = chain.then(() => (ac.signal.aborted ? undefined : speakClause(clause)));
      };

      try {
        const res = await fetch("/api/llm", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            backend: a.lmBackend,
            model: a.lmModel,
            messages: [{ role: "system", content: a.instructions }, ...messagesRef.current],
            maxTokens: a.maxTokens,
            temperature: a.temperature,
          }),
          signal: ac.signal,
        });
        if (!res.ok || !res.body) {
          setCaption("— LM error —");
          throw new Error("llm");
        }
        const reader = res.body.getReader();
        const decoder = new TextDecoder();
        let sse = "";
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          sse += decoder.decode(value, { stream: true });
          const lines = sse.split("\n");
          sse = lines.pop() ?? "";
          for (const line of lines) {
            const t = line.trim();
            if (!t.startsWith("data:")) continue;
            const data = t.slice(5).trim();
            if (data === "[DONE]") continue;
            let delta = "";
            try {
              delta = JSON.parse(data)?.choices?.[0]?.delta?.content ?? "";
            } catch {
              continue;
            }
            if (!delta) continue;
            full += delta;
            buf += delta;
            setCaption(full);
            setTurns((prev) =>
              prev.map((x) => (x.id === agentTurnId ? { ...x, text: full } : x)),
            );
            let seg: [string, string] | null;
            while ((seg = nextClause(buf))) {
              if (seg[0]) enqueue(seg[0]);
              buf = seg[1];
            }
          }
        }
        if (buf.trim()) enqueue(buf.trim());
      } catch {
        // aborted or network error — fall through to cleanup
      }

      messagesRef.current.push({ role: "assistant", content: full });
      setTurns((prev) => prev.map((x) => (x.id === agentTurnId ? { ...x, live: false } : x)));

      await chain; // wait until the last clause finishes speaking
      if (ac.signal.aborted) return;
      speakingRef.current = false;
      if (stateRef.current !== "ended") startListening();
    },
    [setState, speakClause, startListening, stopRecognition],
  );

  const start = useCallback(() => {
    if (stateRef.current !== "idle" && stateRef.current !== "ended") return;
    messagesRef.current = [];
    setTurns([]);
    setState("connecting");
    setCaption("connecting…");
    // Opening line: ask the LM for a greeting, then drop into listening.
    onUserTurn(agentRef.current.firstMessage);
  }, [onUserTurn, setState]);

  const stop = useCallback(() => {
    abortRef.current?.abort();
    speakingRef.current = false;
    stopRecognition();
    if (typeof window !== "undefined") window.speechSynthesis?.cancel();
    setState("ended");
    setCaption("— call ended —");
  }, [setState, stopRecognition]);

  const interrupt = useCallback(() => {
    if (stateRef.current !== "speaking") return;
    abortRef.current?.abort();
    if (typeof window !== "undefined") window.speechSynthesis?.cancel();
    speakingRef.current = false;
    setState("interrupted");
    startListening();
  }, [setState, startListening]);

  const setMuted = useCallback((m: boolean) => {
    mutedRef.current = m;
  }, []);

  // Tear down when the engine is deselected or unmounted.
  useEffect(() => {
    if (active) return;
    return () => {
      abortRef.current?.abort();
      stopRecognition();
      if (typeof window !== "undefined") window.speechSynthesis?.cancel();
      stateRef.current = "idle";
    };
  }, [active, stopRecognition]);

  useEffect(() => {
    return () => {
      abortRef.current?.abort();
      stopRecognition();
      if (typeof window !== "undefined") window.speechSynthesis?.cancel();
    };
  }, [stopRecognition]);

  const getInputVolume = useCallback(() => {
    const s = stateRef.current;
    if (s === "listening" || s === "interrupted")
      return 0.25 + 0.4 * Math.abs(Math.sin(performance.now() / 180));
    return 0.04;
  }, []);
  const getOutputVolume = useCallback(() => {
    if (stateRef.current === "speaking")
      return 0.4 + 0.45 * Math.abs(Math.sin(performance.now() / 140));
    return 0.04;
  }, []);

  return useMemo<CascadeSession>(
    () => ({
      callState,
      turns,
      caption,
      start,
      stop,
      interrupt,
      setMuted,
      getInputVolume,
      getOutputVolume,
    }),
    [callState, turns, caption, start, stop, interrupt, setMuted, getInputVolume, getOutputVolume],
  );
}

