3	// Cascade voice engine: STT → LM → TTS, turn-based, as a SessionApi-compatible
4	// custom engine (same shape as useXaiSession). MVP legs are browser-native so it
5	// works today with only a server-side HF/Mistral key for the LM:
6	//   - STT  → Web Speech API (webkitSpeechRecognition), streaming transcripts
7	//   - LM   → /api/llm (HF Inference router or Mistral), streamed clauses
8	//   - TTS  → Mistral /api/mistral/tts per clause (browser speechSynthesis fallback)
9	// The Mistral realtime-STT leg replaces the Web Speech piece later; the LM and
10	// turn machine stay the same.
11	
12	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
13	import type { Persona } from "@/lib/data";
14	import { resolveCascadeAgent } from "./cascade-agent";
15	import type { CallState, SessionTurn } from "./types";
