17	export interface CascadeSession {
18	  callState: CallState;
19	  turns: SessionTurn[];
20	  caption: string;
21	  start: () => void;
22	  stop: () => void;
23	  interrupt: () => void;
24	  setMuted: (muted: boolean) => void;
25	  getInputVolume: () => number;
26	  getOutputVolume: () => number;
27	}
