29	// ── Minimal Web Speech typings (not in the standard DOM lib) ──────────────────
30	interface SpeechRecognitionAlternative {
31	  transcript: string;
32	}
33	interface SpeechRecognitionResult {
34	  0: SpeechRecognitionAlternative;
35	  isFinal: boolean;
36	}
37	interface SpeechRecognitionEvent {
38	  resultIndex: number;
39	  results: { length: number; [i: number]: SpeechRecognitionResult };
40	}
41	interface SpeechRecognitionLike {
42	  lang: string;
43	  continuous: boolean;
44	  interimResults: boolean;
45	  start: () => void;
46	  stop: () => void;
47	  abort: () => void;
48	  onresult: ((e: SpeechRecognitionEvent) => void) | null;
49	  onend: (() => void) | null;
50	  onerror: ((e: { error?: string }) => void) | null;
51	}
52	type SpeechRecognitionCtor = new () => SpeechRecognitionLike;
53	
54	function getRecognitionCtor(): SpeechRecognitionCtor | null {
55	  if (typeof window === "undefined") return null;
56	  const w = window as unknown as {
57	    SpeechRecognition?: SpeechRecognitionCtor;
58	    webkitSpeechRecognition?: SpeechRecognitionCtor;
59	  };
60	  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
61	}
