63	// Segment a streamed token buffer into speakable clauses (sentence end, or a
64	// clause break once long enough) so TTS starts on the first clause.
65	const SENTENCE_END = /[.!?](?=\s|$)/;
66	const CLAUSE_BREAK = /[,;:](?=\s)/;
67	const MIN_CLAUSE = 30;
68	
69	function nextClause(buf: string): [string, string] | null {
70	  const end = buf.match(SENTENCE_END);
71	  if (end && end.index != null) {
72	    const cut = end.index + 1;
73	    return [buf.slice(0, cut).trim(), buf.slice(cut)];
74	  }
75	  if (buf.length >= MIN_CLAUSE) {
76	    const c = buf.match(CLAUSE_BREAK);
77	    if (c && c.index != null) {
78	      const cut = c.index + 1;
79	      return [buf.slice(0, cut).trim(), buf.slice(cut)];
80	    }
81	  }
82	  return null;
83	}
84	
85	export function useCascadeSession(active: boolean, persona?: Persona): CascadeSession {
86	  const [callState, setCallState] = useState<CallState>("idle");
87	  const [turns, setTurns] = useState<SessionTurn[]>([]);
88	  const [caption, setCaption] = useState("press CALL to begin");
89	
90	  const agent = useMemo(() => resolveCascadeAgent(persona?.id), [persona?.id]);
91	  const agentRef = useRef(agent);
92	  agentRef.current = agent;
93	
94	  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
95	  const messagesRef = useRef<Array<{ role: string; content: string }>>([]);
96	  const mutedRef = useRef(false);
97	  const speakingRef = useRef(false);
98	  const abortRef = useRef<AbortController | null>(null);
99	  const liveTurnId = useRef<string | null>(null);
100	  const currentAudioRef = useRef<HTMLAudioElement | null>(null);
101	  // Breaks the startListening ↔ onUserTurn recursion (each is declared before
102	  // the other needs it); startListening calls through the ref.
103	  const onUserTurnRef = useRef<(t: string) => void>(() => {});
104	
105	  const stateRef = useRef<CallState>("idle");
106	  const setState = useCallback((s: CallState) => {
107	    stateRef.current = s;
108	    setCallState(s);
109	  }, []);
110	
111	  const stopRecognition = useCallback(() => {
112	    const rec = recognitionRef.current;
113	    if (rec) {
114	      rec.onend = null;
115	      try {
116	        rec.abort();
117	      } catch {
118	        // already stopped
119	      }
120	    }
121	  }, []);
122	
123	  const startListening = useCallback(() => {
124	    const Ctor = getRecognitionCtor();
125	    if (!Ctor) {
126	      setCaption("— speech recognition unavailable (use Chrome) —");
127	      return;
128	    }
129	    const rec = new Ctor();
130	    rec.lang = "en-US";
131	    rec.continuous = true;
132	    rec.interimResults = true;
133	    rec.onresult = (e) => {
134	      if (speakingRef.current || mutedRef.current) return;
135	      let interim = "";
136	      let finalText = "";
137	      for (let i = e.resultIndex; i < e.results.length; i++) {
138	        const r = e.results[i];
139	        if (r.isFinal) finalText += r[0].transcript;
140	        else interim += r[0].transcript;
141	      }
142	      if (interim) setCaption(interim);
143	      if (finalText.trim()) onUserTurnRef.current(finalText.trim());
144	    };
145	    rec.onerror = () => {};
146	    // Chrome stops recognition on silence; restart it while we're still listening.
147	    rec.onend = () => {
148	      if (stateRef.current === "listening" && !speakingRef.current) {
149	        try {
150	          rec.start();
151	        } catch {
152	          // start() throws if already running; ignore
153	        }
154	      }
155	    };
156	    recognitionRef.current = rec;
157	    try {
158	      rec.start();
159	    } catch {
160	      // ignore double-start
161	    }
162	    setState("listening");
163	  }, [setState]);
164	
165	  // Browser speechSynthesis fallback (used when the Mistral TTS route fails).
166	  const speakBrowser = useCallback((text: string): Promise<void> => {
167	    return new Promise((resolve) => {
168	      if (typeof window === "undefined" || !window.speechSynthesis) {
169	        resolve();
170	        return;
171	      }
172	      const u = new SpeechSynthesisUtterance(text);
173	      u.onend = () => resolve();
174	      u.onerror = () => resolve();
175	      window.speechSynthesis.speak(u);
176	    });
177	  }, []);
178	
179	  // Speak one clause via Mistral TTS; resolves when playback finishes. Falls back
180	  // to browser speechSynthesis if the route/key is unavailable.
181	  const speakClause = useCallback(
182	    async (text: string, signal: AbortSignal): Promise<void> => {
183	      try {
184	        const res = await fetch("/api/mistral/tts", {
185	          method: "POST",
186	          headers: { "Content-Type": "application/json" },
187	          body: JSON.stringify({ text, voice: agentRef.current.ttsVoice }),
188	          signal,
189	        });
190	        if (!res.ok) throw new Error("tts");
191	        const blob = await res.blob();
192	        if (signal.aborted) return;
193	        const url = URL.createObjectURL(blob);
194	        const audio = new Audio(url);
195	        currentAudioRef.current = audio;
196	        await new Promise<void>((resolve) => {
197	          audio.onended = () => resolve();
198	          audio.onerror = () => resolve();
199	          void audio.play().catch(() => resolve());
200	        });
201	        URL.revokeObjectURL(url);
202	        if (currentAudioRef.current === audio) currentAudioRef.current = null;
203	      } catch {
204	        if (!signal.aborted) await speakBrowser(text);
205	      }
206	    },
207	    [speakBrowser],
208	  );
209	
210	  // Run one assistant turn: stream the LM reply and speak it clause by clause.
211	  const onUserTurn = useCallback(
212	    async (userText: string) => {
213	      stopRecognition();
214	      speakingRef.current = true;
215	      setTurns((prev) => [...prev, { id: `u${prev.length}`, who: "user", text: userText }]);
216	      messagesRef.current.push({ role: "user", content: userText });
217	      setState("speaking");
218	
219	      const a = agentRef.current;
220	      const agentTurnId = `a${Date.now()}`;
221	      liveTurnId.current = agentTurnId;
222	      setTurns((prev) => [...prev, { id: agentTurnId, who: "agent", text: "", live: true }]);
223	
224	      abortRef.current?.abort();
225	      const ac = new AbortController();
226	      abortRef.current = ac;
227	
228	      let buf = "";
229	      let full = "";
230	      const speakQueue: Promise<void> = Promise.resolve();
231	      let chain = speakQueue;
232	
233	      const enqueue = (clause: string) => {
234	        chain = chain.then(() => (ac.signal.aborted ? undefined : speakClause(clause, ac.signal)));
235	      };
236	
237	      try {
238	        const res = await fetch("/api/llm", {
239	          method: "POST",
240	          headers: { "Content-Type": "application/json" },
241	          body: JSON.stringify({
242	            backend: a.lmBackend,
243	            model: a.lmModel,
244	            messages: [{ role: "system", content: a.instructions }, ...messagesRef.current],
245	            maxTokens: a.maxTokens,
246	            temperature: a.temperature,
247	          }),
248	          signal: ac.signal,
249	        });
250	        if (!res.ok || !res.body) {
251	          setCaption("— LM error —");
252	          throw new Error("llm");
253	        }
254	        const reader = res.body.getReader();
255	        const decoder = new TextDecoder();
256	        let sse = "";
257	        while (true) {
258	          const { done, value } = await reader.read();
259	          if (done) break;
260	          sse += decoder.decode(value, { stream: true });
261	          const lines = sse.split("\n");
262	          sse = lines.pop() ?? "";
263	          for (const line of lines) {
264	            const t = line.trim();
265	            if (!t.startsWith("data:")) continue;
266	            const data = t.slice(5).trim();
267	            if (data === "[DONE]") continue;
268	            let delta = "";
269	            try {
270	              delta = JSON.parse(data)?.choices?.[0]?.delta?.content ?? "";
271	            } catch {
272	              continue;
273	            }
274	            if (!delta) continue;
275	            full += delta;
276	            buf += delta;
277	            setCaption(full);
278	            setTurns((prev) => prev.map((x) => (x.id === agentTurnId ? { ...x, text: full } : x)));
279	            let seg: [string, string] | null;
280	            while ((seg = nextClause(buf))) {
281	              if (seg[0]) enqueue(seg[0]);
282	              buf = seg[1];
283	            }
284	          }
285	        }
286	        if (buf.trim()) enqueue(buf.trim());
287	      } catch {
288	        // aborted or network error — fall through to cleanup
289	      }
290	
291	      messagesRef.current.push({ role: "assistant", content: full });
292	      setTurns((prev) => prev.map((x) => (x.id === agentTurnId ? { ...x, live: false } : x)));
293	
294	      await chain; // wait until the last clause finishes speaking
295	      if (ac.signal.aborted) return;
296	      speakingRef.current = false;
297	      if (stateRef.current !== "ended") startListening();
298	    },
299	    [setState, speakClause, startListening, stopRecognition],
300	  );
301	  onUserTurnRef.current = onUserTurn;
302	
303	  const start = useCallback(() => {
304	    if (stateRef.current !== "idle" && stateRef.current !== "ended") return;
305	    messagesRef.current = [];
306	    setTurns([]);
307	    setState("connecting");
308	    setCaption("connecting…");
309	    // Opening line: ask the LM for a greeting, then drop into listening.
310	    onUserTurn(agentRef.current.firstMessage);
311	  }, [onUserTurn, setState]);
312	
313	  const stop = useCallback(() => {
314	    abortRef.current?.abort();
315	    speakingRef.current = false;
316	    stopRecognition();
317	    currentAudioRef.current?.pause();
318	    if (typeof window !== "undefined") window.speechSynthesis?.cancel();
