320	    setCaption("— call ended —");
321	  }, [setState, stopRecognition]);
322	
323	  const interrupt = useCallback(() => {
324	    if (stateRef.current !== "speaking") return;
325	    abortRef.current?.abort();
326	    currentAudioRef.current?.pause();
327	    if (typeof window !== "undefined") window.speechSynthesis?.cancel();
328	    speakingRef.current = false;
