334	    mutedRef.current = m;
335	  }, []);
336	
337	  // Tear down when the engine is deselected or unmounted.
338	  useEffect(() => {
339	    if (active) return;
340	    return () => {
341	      abortRef.current?.abort();
342	      stopRecognition();
343	      currentAudioRef.current?.pause();
344	      if (typeof window !== "undefined") window.speechSynthesis?.cancel();
345	      stateRef.current = "idle";
346	    };
347	  }, [active, stopRecognition]);
348	
349	  useEffect(() => {
350	    return () => {
351	      abortRef.current?.abort();
352	      stopRecognition();
353	      currentAudioRef.current?.pause();
354	      if (typeof window !== "undefined") window.speechSynthesis?.cancel();
355	    };
356	  }, [stopRecognition]);
357	
358	  const getInputVolume = useCallback(() => {
