368	  }, []);
369	
370	  return useMemo<CascadeSession>(
371	    () => ({
372	      callState,
373	      turns,
374	      caption,
375	      start,
376	      stop,
377	      interrupt,
378	      setMuted,
379	      getInputVolume,
380	      getOutputVolume,
381	    }),
382	    [callState, turns, caption, start, stop, interrupt, setMuted, getInputVolume, getOutputVolume],
383	  );
384	}
