() => {
  const txt = (el) => (el.textContent || "").trim();
  // Find the clickable provider row whose text mentions MISTRAL or cascade
  const all = [...document.querySelectorAll('button,[role="button"],li,div,article')];
  const cand = all.filter(b => /MISTRAL|cascade/i.test(txt(b)) && txt(b).length < 200);
  // pick the smallest (most specific) clickable
  cand.sort((a,b) => txt(a).length - txt(b).length);
  const target = cand[0];
  let clicked = false;
  if (target) {
    // climb to a clickable ancestor if needed
    let el = target;
    for (let k = 0; k < 4 && el; k++) {
      if (el.tagName === 'BUTTON' || el.getAttribute('role') === 'button' || el.onclick) { el.click(); clicked = true; break; }
      el = el.parentElement;
    }
    if (!clicked) { target.click(); clicked = true; }
  }
  return JSON.stringify({ found: !!target, sample: target ? txt(target).slice(0,120) : null, clicked });
}

