2	
3	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
4	import { useConversation } from "@elevenlabs/react";
5	import { TRANSCRIPT_SCRIPT, type Persona, type Provider } from "@/lib/data";
6	import type { CallState, SessionApi, SessionTurn } from "./types";
7	import { useXaiSession } from "./use-xai-session";
8	import { useOpenaiSession } from "./use-openai-session";
9	import { useCascadeSession } from "./use-cascade-session";
10	
11	const SCRIPT_TURNS: SessionTurn[] = TRANSCRIPT_SCRIPT.map((t, i) => ({
12	  id: `s${i}`,
13	  who: t.who,
14	  text: t.text,
15	}));
16	
17	const LAST = TRANSCRIPT_SCRIPT.length - 1;
18	
19	function mockCaption(state: CallState): string {
20	  switch (state) {
21	    case "idle":
22	      return "press CALL to begin";
23	    case "ended":
24	      return "— call ended —";
25	    case "connecting":
26	      return "establishing session…";
27	    case "listening":
28	      return TRANSCRIPT_SCRIPT[LAST - 1].text;
29	    case "speaking":
30	      return TRANSCRIPT_SCRIPT[LAST].text;
31	    case "interrupted":
32	      return "… you interrupted";
33	  }
34	}
35	
36	/**
37	 * Unified realtime session. `provider.engine` selects the engine:
38	 *   - undefined → the design's mock lifecycle (timers + TRANSCRIPT_SCRIPT)
39	 *   - "elevenlabs" → real conversation via `@elevenlabs/react`
40	 *   - "xai" → real Grok voice via a direct WebSocket (useXaiSession)
41	 *   - "openai" → real gpt-realtime-2 voice via WebRTC (useOpenaiSession)
42	 * All expose the same `SessionApi` so the UI is provider-agnostic.
43	 *
44	 * `useXaiSession` and `useOpenaiSession` share one interface, so the dispatcher
45	 * picks whichever is active as `custom` and routes every control through it.
46	 *
47	 * All real-engine hooks (`useConversation`, `useXaiSession`, `useOpenaiSession`)
48	 * are called unconditionally (rules of hooks) and stay inert until their engine
49	 * is selected and started.
50	 */
51	export function useRealtimeSession({
52	  provider,
53	  persona,
54	}: {
55	  provider: Provider;
56	  persona?: Persona;
57	}): SessionApi {
58	  const engine = provider.engine;
59	  const isReal = !!engine;
60	
61	  const [callState, setCallState] = useState<CallState>(isReal ? "idle" : "listening");
62	  const [turns, setTurns] = useState<SessionTurn[]>(isReal ? [] : SCRIPT_TURNS);
63	  const [caption, setCaption] = useState<string>(
64	    isReal ? "press CALL to begin" : mockCaption("listening"),
65	  );
66	  const [muted, setMuted] = useState(false);
67	  const [elapsed, setElapsed] = useState(0);
68	
69	  const stateRef = useRef(callState);
70	  stateRef.current = callState;
71	  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
72	  const clearTimers = () => {
73	    timers.current.forEach(clearTimeout);
74	    timers.current = [];
75	  };
76	
77	  // ── ElevenLabs real conversation ──────────────────────────────────────────
78	  const realPhase = useRef<"idle" | "active" | "ended">("idle");
79	  const conversation = useConversation({
80	    micMuted: muted,
81	    onMessage: (msg: { source?: string; message?: string }) => {
82	      const who = msg.source === "user" ? "user" : "agent";
83	      const text = msg.message ?? "";
84	      if (!text) return;
85	      setTurns((prev) => [...prev, { id: `r${prev.length}`, who, text }]);
86	      setCaption(text);
87	    },
88	    onError: () => {
89	      realPhase.current = "ended";
90	      setCallState("ended");
91	      setCaption("— connection error —");
92	    },
93	  });
94	
95	  const { status, mode, isSpeaking, startSession, endSession } = conversation;
96	
97	  // ── Custom real engines (own WebSocket / WebRTC, shared interface) ─────────
98	  const xai = useXaiSession(engine === "xai", persona);
99	  const openai = useOpenaiSession(engine === "openai", persona);
100	  const cascade = useCascadeSession(engine === "cascade", persona);
101	  // Whichever custom engine is active owns the session; null ⇒ ElevenLabs/mock.
102	  const custom =
103	    engine === "xai" ? xai : engine === "openai" ? openai : engine === "cascade" ? cascade : null;
104	
105	  // The active call state comes from whichever engine owns the session.
106	  const activeCallState: CallState = custom ? custom.callState : callState;
107	
108	  // Derive real CallState from the conversation status/mode (ElevenLabs only).
109	  useEffect(() => {
110	    if (engine !== "elevenlabs" || realPhase.current === "idle") return;
111	    if (realPhase.current === "ended") {
112	      setCallState("ended");
113	      return;
114	    }
115	    if (status === "connecting") setCallState("connecting");
116	    else if (status === "error") setCallState("ended");
117	    else if (status === "disconnected") setCallState("ended");
118	    else if (status === "connected") {
119	      setCallState(mode === "speaking" || isSpeaking ? "speaking" : "listening");
120	      setCaption((c) => (c === "establishing session…" ? "listening…" : c));
121	    }
122	  }, [engine, status, mode, isSpeaking]);
123	
124	  // ── Mock lifecycle ──────────────────────────────────────────────────────────
125	  // First-load drift: listening → speaking after 5s (matches the prototype).
126	  useEffect(() => {
127	    if (isReal) return;
128	    if (callState !== "listening") return;
129	    const t = setTimeout(() => setCallState("speaking"), 5000);
130	    return () => clearTimeout(t);
131	    // eslint-disable-next-line react-hooks/exhaustive-deps
132	  }, [isReal]);
133	
134	  // Caption sync for the mock engine.
135	  useEffect(() => {
136	    if (isReal) return;
137	    setCaption(mockCaption(callState));
138	  }, [isReal, callState]);
139	
140	  // Elapsed ticker (all engines) — keyed off whichever engine owns the call.
141	  useEffect(() => {
142	    if (activeCallState === "idle" || activeCallState === "ended") {
143	      setElapsed(0);
144	      return;
145	    }
146	    const t = setInterval(() => setElapsed((e) => e + 1), 1000);
147	    return () => clearInterval(t);
148	  }, [activeCallState]);
149	
150	  // Push mute into the active real engine. ElevenLabs only accepts setMuted once
151	  // connected (it throws "No active conversation" before startSession()); xAI
152	  // gates its own mic send, so it's always safe.
153	  useEffect(() => {
