48	export class MistralStt {
49	  private readonly opts: MistralSttOptions;
50	  private ws: WebSocket | null = null;
51	  private ctx: AudioContext | null = null;
52	  private stream: MediaStream | null = null;
53	  private source: MediaStreamAudioSourceNode | null = null;
54	  private proc: ScriptProcessorNode | null = null;
55	
56	  // Capture gating: audio is streamed only while listening && !muted.
57	  private listening = false;
58	  private muted = false;
59	  private closed = false;
60	  private ready = false;
61	
62	  // Per-turn transcript + VAD state.
63	  private turnText = "";
64	  private voiceMs = 0;
65	  private hadSpeech = false;
66	  private silenceMs = 0;
67	  private emitting = false;
68	  private flushTimer: ReturnType<typeof setTimeout> | null = null;
69	  private inputRms = 0;
70	  // Adaptive background-noise estimate (EMA over silent frames).
71	  private noiseFloor = 0.01;
