77	  /** Open the mic + proxy WebSocket and configure the session. Resolves once
78	   *  the audio graph and socket are wired (not necessarily server-ready). */
79	  async start(): Promise<void> {
80	    this.closed = false;
81	    const ctx = new AudioContext({ sampleRate: SAMPLE_RATE });
82	    this.ctx = ctx;
83	
84	    const stream = await navigator.mediaDevices.getUserMedia({
85	      audio: {
