87	        echoCancellation: true,
88	        noiseSuppression: true,
89	        // AGC boosts ambient noise enough to trip the VAD — keep it off so the
90	        // silence gate stays stable (same lesson as the PersonaPlex mic gate).
91	        autoGainControl: false,
92	      },
93	    });
94	    if (this.closed) {
95	      stream.getTracks().forEach((t) => t.stop());
96	      return;
97	    }
98	    this.stream = stream;
99	    if (ctx.state === "suspended") await ctx.resume();
100	
101	    const source = ctx.createMediaStreamSource(stream);
102	    this.source = source;
103	    const proc = ctx.createScriptProcessor(PROC_FRAMES, 1, 1);
104	    this.proc = proc;
105	    const frameMs = (PROC_FRAMES / SAMPLE_RATE) * 1000;
106	    proc.onaudioprocess = (e) => this.onAudio(e.inputBuffer.getChannelData(0), frameMs);
