115	  private connectWs(): void {
116	    const model = this.opts.model ?? "voxtral-mini-transcribe-realtime-2602";
117	    const url = `${this.opts.wsUrl}?model=${encodeURIComponent(model)}`;
118	    let ws: WebSocket;
119	    try {
120	      ws = new WebSocket(url);
121	    } catch {
122	      this.opts.onError?.("STT proxy unreachable");
123	      return;
124	    }
125	    this.ws = ws;
126	    ws.onopen = () => {
127	      ws.send(
128	        JSON.stringify({
129	          type: "session.update",
130	          session: {
131	            audio_format: { encoding: "pcm_s16le", sample_rate: SAMPLE_RATE },
132	            target_streaming_delay_ms: 1000,
133	          },
134	        }),
135	      );
136	    };
137	    ws.onmessage = (ev) => this.onMessage(ev);
138	    ws.onerror = () => {
139	      if (!this.closed) this.opts.onError?.("STT proxy connection error");
140	    };
141	    ws.onclose = () => {
142	      if (!this.closed && this.ready) this.opts.onError?.("STT session closed");
143	    };
144	  }
145	
146	  private onMessage(ev: MessageEvent): void {
147	    let msg: { type?: string; text?: string };
148	    try {
149	      msg = JSON.parse(typeof ev.data === "string" ? ev.data : "{}");
150	    } catch {
151	      return;
152	    }
153	    switch (msg.type) {
154	      case "session.updated":
155	        if (!this.ready) {
156	          this.ready = true;
157	          this.opts.onReady?.();
158	        }
159	        break;
160	      case "transcription.text.delta":
