166	        }
167	        break;
168	      case "error":
169	        this.opts.onError?.("STT error");
170	        break;
171	      default:
172	        break;
173	    }
174	  }
175	
176	  private onAudio(input: Float32Array, frameMs: number): void {
177	    if (this.muted || !this.listening) {
178	      this.inputRms = 0;
179	      return;
180	    }
181	    const rms = calculateRms(input);
182	    this.inputRms = rms;
183	
