232	  private resetTurn(): void {
233	    this.turnText = "";
234	    this.voiceMs = 0;
235	    this.silenceMs = 0;
236	    this.hadSpeech = false;
237	  }
238	
239	  /** Resume capturing the user (call when entering the listening state). */
240	  resume(): void {
241	    this.resetTurn();
242	    this.emitting = false;
243	    if (this.flushTimer) {
