272	  }
273	
274	  /** Tear everything down. */
275	  stop(): void {
276	    this.closed = true;
277	    this.listening = false;
278	    if (this.flushTimer) {
279	      clearTimeout(this.flushTimer);
280	      this.flushTimer = null;
281	    }
282	    if (this.proc) {
283	      this.proc.onaudioprocess = null;
