/** Resume capturing the user (call when entering the listening state). */
resume(): void {
  this.resetTurn();
  this.emitting = false;
  if (this.flushTimer) {
    clearTimeout(this.flushTimer);
    this.flushTimer = null;
  }
  this.listening = true;
}

