async () => {
  const ort = await import("https://cdn.jsdelivr.net/npm/onnxruntime-web@1.27.0/dist/ort.min.mjs");
  ort.env.wasm.numThreads = 1;
  ort.env.wasm.wasmPaths = "https://cdn.jsdelivr.net/npm/onnxruntime-web@1.27.0/dist/";
  const session = await ort.InferenceSession.create("/silero_vad_v5.onnx", { executionProviders: ["wasm"] });

  // Load the served 16k mono s16le speech clip → Float32 [-1,1].
  const buf = await (await fetch("/utt-test.pcm")).arrayBuffer();
  const i16 = new Int16Array(buf);
  const f32 = new Float32Array(i16.length);
  for (let i = 0; i < i16.length; i++) f32[i] = i16[i] / (i16[i] < 0 ? 0x8000 : 0x7fff);

  const FRAME = 512;
  let state = new ort.Tensor("float32", new Float32Array(2 * 1 * 128), [2, 1, 128]);
  const sr = new ort.Tensor("int64", new BigInt64Array([16000n]), [1]);
  const probs = [];
  for (let off = 0; off + FRAME <= f32.length; off += FRAME) {
    const input = new ort.Tensor("float32", f32.slice(off, off + FRAME), [1, FRAME]);
    const out = await session.run({ input, state, sr });
    state = out.stateN;
    probs.push(out.output.data[0]);
  }
  const max = Math.max(...probs);
  const speechFrames = probs.filter(p => p > 0.5).length;
  // tail probabilities (last ~10 frames ≈ 320ms) should drop → end-of-speech
  const tail = probs.slice(-10).map(p => +p.toFixed(2));
  return JSON.stringify({ totalFrames: probs.length, maxProb: +max.toFixed(3), speechFrames, tailProbs: tail });
}

async () => {
  const ort = await import("https://cdn.jsdelivr.net/npm/onnxruntime-web@1.27.0/dist/ort.min.mjs");
  ort.env.wasm.numThreads = 1;
  ort.env.wasm.wasmPaths = "https://cdn.jsdelivr.net/npm/onnxruntime-web@1.27.0/dist/";
  const session = await ort.InferenceSession.create("/silero_vad_v5.onnx", { executionProviders: ["wasm"] });
  const buf = await (await fetch("/utt-silence.pcm")).arrayBuffer();
  const i16 = new Int16Array(buf);
  const f32 = new Float32Array(i16.length);
  for (let i = 0; i < i16.length; i++) f32[i] = i16[i] / (i16[i] < 0 ? 0x8000 : 0x7fff);

  // Replicate SileroVad's state machine with the app's tunables.
  const FRAME = 512, FRAME_MS = 32;
  const POS = 0.3, NEG = 0.25, redemptionFrames = Math.round(900/FRAME_MS), minSpeechFrames = Math.round(250/FRAME_MS);
  let state = new ort.Tensor("float32", new Float32Array(256), [2,1,128]);
  const sr = new ort.Tensor("int64", new BigInt64Array([16000n]), [1]);
  let speaking=false, redemption=0, speechFrames=0, frameIdx=0, speechStartFrame=null, speechEndFrame=null;
  for (let off=0; off+FRAME<=f32.length; off+=FRAME, frameIdx++) {
    const input = new ort.Tensor("float32", f32.slice(off, off+FRAME), [1,FRAME]);
    const out = await session.run({ input, state, sr }); state = out.stateN;
    const p = out.output.data[0];
    if (p>=POS) { if(!speaking){speaking=true;speechFrames=0;redemption=0;if(speechStartFrame===null)speechStartFrame=frameIdx;} speechFrames++; redemption=0; }
    else if (speaking) { if(p<NEG){ if(++redemption>=redemptionFrames){ if(speechFrames>=minSpeechFrames && speechEndFrame===null) speechEndFrame=frameIdx; speaking=false; redemption=0; } } else redemption=0; }
  }
  return JSON.stringify({
    totalFrames: frameIdx,
    speechStart_ms: speechStartFrame!=null ? speechStartFrame*FRAME_MS : null,
    speechEnd_ms: speechEndFrame!=null ? speechEndFrame*FRAME_MS : null,
    fired_onSpeechEnd: speechEndFrame!=null,
  });
}

