  const i16 = new Int16Array(buf);
  const f32 = new Float32Array(i16.length);
  for (let i = 0; i < i16.length; i++) f32[i] = i16[i] / (i16[i] < 0 ? 0x8000 : 0x7fff);

  const FRAME = 512, FRAME_MS = 32;
  const POS = 0.3, NEG = 0.25, redemptionFrames = Math.round(900/FRAME_MS), minSpeechFrames = Math.round(250/FRAME_MS);
  let state = new ort.Tensor("float32", new Float32Array(256), [2,1,128]);
  const sr = new ort.Tensor("int64", new BigInt64Array([16000n]), [1]);
  let speaking=false, redemption=0, speechFrames=0, idx=0, startMs=null, endMs=null, maxP=0;
  for (let off=0; off+FRAME<=f32.length; off+=FRAME, idx++) {
    const input = new ort.Tensor("float32", f32.slice(off, off+FRAME), [1,FRAME]);
    const out = await session.run({ input, state, sr }); state = out.stateN;
    const p = out.output.data[0]; maxP = Math.max(maxP, p);
    if (p>=POS){ if(!speaking){speaking=true;speechFrames=0;redemption=0;if(startMs===null)startMs=idx*FRAME_MS;} speechFrames++; redemption=0; }
    else if (speaking){ if(p<NEG){ if(++redemption>=redemptionFrames){ if(speechFrames>=minSpeechFrames && endMs===null) endMs=idx*FRAME_MS; speaking=false; redemption=0; } } else redemption=0; }
  }
  return JSON.stringify({ inputNames: session.inputNames, outputNames: session.outputNames, maxProb:+maxP.toFixed(3), speechStart_ms:startMs, speechEnd_ms:endMs, fired:endMs!=null });
}

async () => {
  const ort = await import("https://cdn.jsdelivr.net/npm/onnxruntime-web@1.27.0/dist/ort.min.mjs");
  ort.env.wasm.numThreads = 1;
  ort.env.wasm.wasmPaths = "https://cdn.jsdelivr.net/npm/onnxruntime-web@1.27.0/dist/";
  const session = await ort.InferenceSession.create("/silero_vad.onnx", { executionProviders: ["wasm"] });
  const buf = await (await fetch("/utt-silence.pcm")).arrayBuffer();
  const i16 = new Int16Array(buf);
  const f32 = new Float32Array(i16.length);
  for (let i = 0; i < i16.length; i++) f32[i] = i16[i] / (i16[i] < 0 ? 0x8000 : 0x7fff);

  const FRAME = 512, CTX = 64;
  const sr = new ort.Tensor("int64", new BigInt64Array([16000n]), [1]);

  // Variant A: 512 direct (no context). Variant B: 64-sample context + 512 = 576.
  async function run(useContext) {
    let state = new ort.Tensor("float32", new Float32Array(256), [2,1,128]);
    let context = new Float32Array(CTX);
    let maxP = 0, hi = 0, n = 0;
    for (let off=0; off+FRAME<=f32.length; off+=FRAME) {
      const frame = f32.subarray(off, off+FRAME);
      let inData, len;
      if (useContext) { const m = new Float32Array(CTX+FRAME); m.set(context,0); m.set(frame,CTX); inData=m; len=CTX+FRAME; context = frame.slice(FRAME-CTX); }
      else { inData = frame; len = FRAME; }
      const input = new ort.Tensor("float32", inData, [1, len]);
      const out = await session.run({ input, state, sr }); state = out.stateN;
      const p = out.output.data[0]; maxP=Math.max(maxP,p); if(p>0.5)hi++; n++;
    }
    return { maxProb:+maxP.toFixed(3), speechFrames:hi, total:n };
  }
  return JSON.stringify({ direct512: await run(false), context576: await run(true) });
}

