() => {
  const reqs = performance.getEntriesByType("resource").map(r => ({u:r.name, ok: r.responseStatus || (r.transferSize>=0)}))
    .filter(r => /silero|onnxruntime|\.wasm/i.test(r.u)).map(r => r.u);
  const state = ((document.querySelector('.tb-call-state-l') || {}).textContent || "").trim();
