/* Manual-turn "hold" ring — a held, slowly-rotating dashed ring shown only while
   LISTENING on a half-duplex (cascade) engine, where the turn ends on SEND. Reads
   differently from the auto pulse rings, which would imply automatic end-of-turn. */
.tb-orb-hold {
  position: absolute;
  inset: -7%;
  border: 1.5px dashed var(--accent);
  border-radius: 50%;
  pointer-events: none;
  animation: tb-orb-hold 9s linear infinite;
}
@keyframes tb-orb-hold {
  0% {
    transform: rotate(0deg) scale(1);
    opacity: 0.7;
  }
  50% {
    transform: rotate(180deg) scale(1.04);
    opacity: 0.95;
  }
  100% {
    transform: rotate(360deg) scale(1);
    opacity: 0.7;
  }
}
@media (prefers-reduced-motion: reduce) {
  .tb-orb-hold {
    animation: none;
    opacity: 0.85;
  }
}

