// provider-table.tsx — the realtime-transport roster as a selectable brutalist
// table. One radio-row per provider (vendor · model · region · p50 · status ·
// note); the active row gets an accent outline + filled radio.

import type { CSSProperties } from "react";
import { Tag } from "./primitives";
import type { ProviderData } from "./types";

export interface ProviderTableProps {
  /** Providers to list. */
  providers: ProviderData[];
  /** Selected provider id. */
  activeId?: string;
  /** Row select handler. */
  onSelect?: (provider: ProviderData) => void;
  /** Accent color for the active radio (defaults to inherited --accent). */
  accent?: string;
}

export function ProviderTable({ providers, activeId, onSelect, accent }: ProviderTableProps) {
  const a = accent ?? "var(--accent)";
  return (
    <table className="pp-table">
      <thead>
        <tr>
          <th style={{ width: 32 }} />
          <th>VENDOR</th>
          <th>MODEL</th>
          <th>REGION</th>
          <th style={{ textAlign: "right" }}>P50 LAT</th>
          <th>STATUS</th>
          <th>NOTES</th>
        </tr>
      </thead>
      <tbody>
        {providers.map((p) => {
          const on = p.id === activeId;
          const radioStyle: CSSProperties | undefined = on
            ? { background: a, borderColor: a }
            : undefined;
          return (
            <tr key={p.id} className={on ? "on" : ""} onClick={() => onSelect?.(p)}>
              <td className="pp-table-radio">
                <span className={on ? "on" : ""} style={radioStyle} />
              </td>
              <td className="pp-table-vendor">{p.name}</td>
              <td className="pp-mono-num">{p.model}</td>
              <td>{p.region}</td>
              <td className="pp-mono-num" style={{ textAlign: "right" }}>
                {p.latency} ms
              </td>
              <td>
                <Tag mono dot>
                  {p.status.toUpperCase()}
                </Tag>
              </td>
              <td className="pp-table-note">{p.note}</td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
}

