// types.ts — shared domain shapes for the data-driven Tsubaki components.

export interface Tool {
  /** Machine name, e.g. `search.web`. */
  name: string;
  /** Human label, e.g. "Web search · Tavily". */
  label: string;
  /** Armed state. */
  on: boolean;
}

export interface PersonaData {
  id: string;
  /** Display name, e.g. "ARIA". */
  name: string;
  /** Accent/gender tag, e.g. "AMER · F". */
  accent: string;
  /** Short trait chips. */
  traits: string[];
  /** Voice descriptor, e.g. "Mezzo · 220–340 Hz". */
  voice: string;
  /** One-line description. */
  desc: string;
  /** Words per minute. */
  wpm: number;
}

export interface ProviderData {
  id: string;
  /** Vendor, e.g. "XAI". */
  name: string;
  /** Model id, e.g. "grok-voice-latest". */
  model: string;
  /** p50 latency in ms. */
  latency: number;
  /** Rollout status. */
  status: "ready" | "beta";
  /** Region tag, e.g. "US-WEST". */
  region: string;
  /** Free-text note. */
  note: string;
  /** Which real engine drives the row (absent ⇒ mock). */
  engine?: "elevenlabs" | "xai" | "openai" | "cascade";
}

export interface TranscriptTurnData {
  who: "agent" | "user";
  text: string;
}

