1	// Catalog of LM models + backends for the cascade (STT → LM → TTS) engine.
2	//
3	// Single source of truth, edited as data in `config/lm-models.json` — so changing
4	// which model the cascade uses is a config edit, not a code change, and there's no
5	// need to pull a live model list. Read by both the server route (`app/api/llm`,
6	// which resolves a backend's URL + secret env key) and the client agent config
7	// (`cascade-agent.ts`, which picks the model). Only env var *names* and public
8	// API URLs live here; secret values stay in fnox and are read server-side.
9	
10	import catalog from "@/config/lm-models.json";
11	
12	export interface LmBackendConfig {
13	  /** OpenAI-compatible chat-completions endpoint. */
14	  url: string;
15	  /** Name of the secret env var holding the bearer token (read server-side only). */
16	  envKey: string;
17	  /** Send chat_template_kwargs.enable_thinking:false (reasoning models). Must be
18	   *  false for APIs that reject unknown fields (e.g. Mistral). */
19	  supportsThinking: boolean;
20	}
21	
22	export interface LmModel {
23	  /** Stable key used by `default` / a persona's `lmModelId`. */
24	  id: string;
25	  /** Human label (for docs / a future picker). */
26	  label: string;
27	  /** Backend id — a key of `backends`. */
28	  backend: string;
29	  /** Upstream model id (HF repo or Mistral model name). */
30	  model: string;
31	  temperature: number;
32	  maxTokens: number;
33	}
34	
35	interface LmCatalog {
36	  default: string;
37	  backends: Record<string, LmBackendConfig>;
38	  models: LmModel[];
39	}
40	
41	const CONFIG = catalog as unknown as LmCatalog;
42	
43	export const LM_BACKENDS: Record<string, LmBackendConfig> = CONFIG.backends;
44	export const LM_MODELS: LmModel[] = CONFIG.models;
45	
46	/** Look up a backend by id (undefined if not in the catalog). */
47	export function resolveLmBackend(id: string): LmBackendConfig | undefined {
48	  return LM_BACKENDS[id];
49	}
50	
51	/** Resolve a model by id, falling back to the catalog `default`, then the first
52	 *  entry — so a stale/empty id never breaks a call. */
53	export function resolveLmModel(id?: string): LmModel {
54	  return (
55	    (id ? LM_MODELS.find((m) => m.id === id) : undefined) ??
56	    LM_MODELS.find((m) => m.id === CONFIG.default) ??
57	    LM_MODELS[0]
58	  );
59	}
60	
61	/** The catalog default — the model every cascade persona uses unless it pins one. */
62	export const DEFAULT_LM_MODEL: LmModel = resolveLmModel(CONFIG.default);
63	
64	/** Selectable LM models for a provider's engine. Only the cascade engine draws
65	 *  from the catalog; every other engine is a single fixed realtime model (so the
66	 *  Providers view shows no model picker for them). */
67	export function lmModelsForEngine(engine?: string): LmModel[] {
68	  return engine === "cascade" ? LM_MODELS : [];
69	}
