110	/** Merge the selected persona over the catalog-driven model defaults. Model
111	 *  precedence: an explicit UI selection (`overrideModelId`, from the Providers
112	 *  picker) > the persona's `lmModelId` pin > the catalog default. An explicit
113	 *  `lmBackend`/`lmModel`/etc. on the persona still wins over all of that. */
114	export function resolveCascadeAgent(
115	  personaId?: string,
116	  overrideModelId?: string,
117	): CascadeAgentConfig {
118	  const persona = (personaId && PERSONA_AGENTS[personaId]) || DEFAULT_PERSONA_AGENT;
119	  const { lmModelId, ...personaConfig } = persona;
120	  const modelId = overrideModelId ?? lmModelId;
