1	// Mistral text-to-speech for the cascade engine's TTS leg.
2	//
3	// POST { text, voice } → calls Mistral /v1/audio/speech (voxtral-mini-tts) and
4	// returns the decoded MP3 bytes so the browser can play the blob directly. The
5	// MISTRAL_API_KEY stays server-side (provided via fnox).
6	//
7	// Mistral returns `{ audio_data: <base64> }` (non-streaming); we decode it and
8	// hand back audio/mpeg. Per-clause calls keep each request short and let the
9	// engine pipeline playback while the LM streams the next clause.
10	
11	export const runtime = "nodejs";
12	export const dynamic = "force-dynamic";
13	
14	const SPEECH_URL = "https://api.mistral.ai/v1/audio/speech";
15	const MODEL = "voxtral-mini-tts-2603";
16	const DEFAULT_VOICE = "en_paul_neutral";
17	
18	interface TtsRequest {
19	  text?: string;
20	  voice?: string;
21	}
22	
23	export async function POST(req: Request): Promise<Response> {
24	  const apiKey = process.env.MISTRAL_API_KEY;
25	  if (!apiKey) {
26	    return Response.json(
27	      { error: "MISTRAL_API_KEY is not set on the server (provide it via fnox)." },
28	      { status: 500 },
29	    );
30	  }
31	
32	  let body: TtsRequest;
33	  try {
34	    body = (await req.json()) as TtsRequest;
35	  } catch {
36	    return Response.json({ error: "Invalid JSON body." }, { status: 400 });
37	  }
38	  const text = body.text?.trim();
39	  if (!text) return Response.json({ error: "text is required." }, { status: 400 });
40	
41	  let upstream: Response;
42	  try {
43	    upstream = await fetch(SPEECH_URL, {
44	      method: "POST",
45	      headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json" },
46	      body: JSON.stringify({
47	        model: MODEL,
48	        input: text,
49	        voice_id: body.voice || DEFAULT_VOICE,
50	        response_format: "mp3",
51	      }),
52	    });
53	  } catch (err) {
54	    return Response.json(
55	      { error: `Failed to reach Mistral: ${err instanceof Error ? err.message : "network error"}` },
56	      { status: 502 },
57	    );
58	  }
59	
60	  if (!upstream.ok) {
61	    const detail = await upstream.text().catch(() => "");
62	    return Response.json(
63	      { error: "Mistral speech request failed", status: upstream.status, detail },
64	      { status: 502 },
65	    );
66	  }
67	
68	  const json = (await upstream.json()) as { audio_data?: string };
69	  if (!json.audio_data) {
70	    return Response.json({ error: "Mistral returned no audio_data." }, { status: 502 });
71	  }
72	  const bytes = Buffer.from(json.audio_data, "base64");
73	  return new Response(bytes, {
74	    status: 200,
75	    headers: { "Content-Type": "audio/mpeg", "Cache-Control": "no-store" },
76	  });
77	}
