3	// Cascade voice engine: STT → LM → TTS, turn-based, as a SessionApi-compatible
4	// custom engine (same shape as useXaiSession). MVP legs are browser-native so it
5	// works today with only a server-side HF/Mistral key for the LM:
6	//   - STT  → Web Speech API (webkitSpeechRecognition), streaming transcripts
7	//   - LM   → /api/llm (HF Inference router or Mistral), streamed clauses
8	//   - TTS  → Mistral /api/mistral/tts per clause (browser speechSynthesis fallback)
9	// The Mistral realtime-STT leg replaces the Web Speech piece later; the LM and
10	// turn machine stay the same.
11	
12	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
13	import type { Persona } from "@/lib/data";
14	import { resolveCascadeAgent } from "./cascade-agent";
15	import { MistralStt } from "./mistral-stt";
16	import type { CallState, SessionTurn } from "./types";
17	
18	// Local WS proxy that adds the Mistral Bearer header the browser can't set.
19	// Public (non-secret) URL; override with NEXT_PUBLIC_MISTRAL_STT_WS.
20	const STT_WS_URL = process.env.NEXT_PUBLIC_MISTRAL_STT_WS ?? "ws://localhost:3001";
21	
22	export interface CascadeSession {
23	  callState: CallState;
24	  turns: SessionTurn[];
25	  caption: string;
26	  start: () => void;
27	  stop: () => void;
28	  interrupt: () => void;
29	  sendTurn: () => void;
30	  setMuted: (muted: boolean) => void;
31	  getInputVolume: () => number;
32	  getOutputVolume: () => number;
33	}
34	
35	// ── Minimal Web Speech typings (not in the standard DOM lib) ──────────────────
36	interface SpeechRecognitionAlternative {
37	  transcript: string;
38	}
39	interface SpeechRecognitionResult {
40	  0: SpeechRecognitionAlternative;
41	  isFinal: boolean;
42	}
43	interface SpeechRecognitionEvent {
44	  resultIndex: number;
45	  results: { length: number; [i: number]: SpeechRecognitionResult };
46	}
47	interface SpeechRecognitionLike {
48	  lang: string;
49	  continuous: boolean;
50	  interimResults: boolean;
51	  start: () => void;
52	  stop: () => void;
53	  abort: () => void;
54	  onresult: ((e: SpeechRecognitionEvent) => void) | null;
55	  onend: (() => void) | null;
56	  onerror: ((e: { error?: string }) => void) | null;
57	}
58	type SpeechRecognitionCtor = new () => SpeechRecognitionLike;
59	
60	function getRecognitionCtor(): SpeechRecognitionCtor | null {
61	  if (typeof window === "undefined") return null;
62	  const w = window as unknown as {
63	    SpeechRecognition?: SpeechRecognitionCtor;
64	    webkitSpeechRecognition?: SpeechRecognitionCtor;
65	  };
66	  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
67	}
68	
69	// Segment a streamed token buffer into speakable clauses (sentence end, or a
70	// clause break once long enough) so TTS starts on the first clause.
71	const SENTENCE_END = /[.!?](?=\s|$)/;
72	const CLAUSE_BREAK = /[,;:](?=\s)/;
73	const MIN_CLAUSE = 30;
74	
75	function nextClause(buf: string): [string, string] | null {
76	  const end = buf.match(SENTENCE_END);
77	  if (end && end.index != null) {
78	    const cut = end.index + 1;
79	    return [buf.slice(0, cut).trim(), buf.slice(cut)];
80	  }
81	  if (buf.length >= MIN_CLAUSE) {
82	    const c = buf.match(CLAUSE_BREAK);
83	    if (c && c.index != null) {
84	      const cut = c.index + 1;
85	      return [buf.slice(0, cut).trim(), buf.slice(cut)];
86	    }
87	  }
88	  return null;
89	}
90	
91	export function useCascadeSession(
92	  active: boolean,
93	  persona?: Persona,
94	  lmModelId?: string,
95	): CascadeSession {
96	  const [callState, setCallState] = useState<CallState>("idle");
97	  const [turns, setTurns] = useState<SessionTurn[]>([]);
98	  const [caption, setCaption] = useState("press CALL to begin");
99	
100	  // Re-resolves when the persona or the picked LM model changes; agentRef is
101	  // updated every render, so a model switch applies on the next turn.
102	  const agent = useMemo(
103	    () => resolveCascadeAgent(persona?.id, lmModelId),
104	    [persona?.id, lmModelId],
105	  );
106	  const agentRef = useRef(agent);
107	  agentRef.current = agent;
108	
109	  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
