111	  // mic is unavailable, in which case usingMistralRef flips to false.
112	  const sttRef = useRef<MistralStt | null>(null);
113	  const usingMistralRef = useRef(false);
114	  const messagesRef = useRef<Array<{ role: string; content: string }>>([]);
115	  const mutedRef = useRef(false);
116	  const speakingRef = useRef(false);
117	  const abortRef = useRef<AbortController | null>(null);
118	  const liveTurnId = useRef<string | null>(null);
119	  const currentAudioRef = useRef<HTMLAudioElement | null>(null);
120	  // Breaks the startListening ↔ onUserTurn recursion (each is declared before
121	  // the other needs it); startListening calls through the ref.
122	  const onUserTurnRef = useRef<(t: string) => void>(() => {});
123	
124	  const stateRef = useRef<CallState>("idle");
125	  const setState = useCallback((s: CallState) => {
126	    stateRef.current = s;
127	    setCallState(s);
128	  }, []);
129	
130	  const stopRecognition = useCallback(() => {
131	    const rec = recognitionRef.current;
132	    if (rec) {
133	      rec.onend = null;
134	      try {
135	        rec.abort();
136	      } catch {
137	        // already stopped
138	      }
139	    }
140	  }, []);
141	
142	  const startListening = useCallback(() => {
143	    const Ctor = getRecognitionCtor();
144	    if (!Ctor) {
145	      setCaption("— speech recognition unavailable (use Chrome) —");
146	      return;
147	    }
148	    const rec = new Ctor();
149	    rec.lang = "en-US";
150	    rec.continuous = true;
151	    rec.interimResults = true;
152	    rec.onresult = (e) => {
153	      if (speakingRef.current || mutedRef.current) return;
154	      let interim = "";
155	      let finalText = "";
156	      for (let i = e.resultIndex; i < e.results.length; i++) {
157	        const r = e.results[i];
158	        if (r.isFinal) finalText += r[0].transcript;
159	        else interim += r[0].transcript;
