246	      }
247	    },
248	    [speakBrowser],
249	  );
250	
251	  // Run one assistant turn: stream the LM reply and speak it clause by clause.
252	  const onUserTurn = useCallback(
253	    async (userText: string) => {
254	      endListening();
255	      speakingRef.current = true;
256	      setTurns((prev) => [...prev, { id: `u${prev.length}`, who: "user", text: userText }]);
257	      messagesRef.current.push({ role: "user", content: userText });
258	      setState("speaking");
259	
260	      const a = agentRef.current;
261	      const agentTurnId = `a${Date.now()}`;
262	      liveTurnId.current = agentTurnId;
263	      setTurns((prev) => [...prev, { id: agentTurnId, who: "agent", text: "", live: true }]);
264	
265	      abortRef.current?.abort();
266	      const ac = new AbortController();
267	      abortRef.current = ac;
268	
269	      let buf = "";
270	      let full = "";
271	      const speakQueue: Promise<void> = Promise.resolve();
272	      let chain = speakQueue;
273	
274	      const enqueue = (clause: string) => {
275	        chain = chain.then(() => (ac.signal.aborted ? undefined : speakClause(clause, ac.signal)));
276	      };
