278	      try {
279	        const res = await fetch("/api/llm", {
280	          method: "POST",
281	          headers: { "Content-Type": "application/json" },
282	          body: JSON.stringify({
283	            backend: a.lmBackend,
284	            model: a.lmModel,
285	            messages: [{ role: "system", content: a.instructions }, ...messagesRef.current],
286	            maxTokens: a.maxTokens,
287	            temperature: a.temperature,
288	          }),
289	          signal: ac.signal,
290	        });
291	        if (!res.ok || !res.body) {
292	          setCaption("— LM error —");
293	          throw new Error("llm");
294	        }
295	        const reader = res.body.getReader();
296	        const decoder = new TextDecoder();
297	        let sse = "";
298	        while (true) {
299	          const { done, value } = await reader.read();
300	          if (done) break;
301	          sse += decoder.decode(value, { stream: true });
302	          const lines = sse.split("\n");
303	          sse = lines.pop() ?? "";
304	          for (const line of lines) {
305	            const t = line.trim();
306	            if (!t.startsWith("data:")) continue;
307	            const data = t.slice(5).trim();
308	            if (data === "[DONE]") continue;
309	            let delta = "";
310	            try {
311	              delta = JSON.parse(data)?.choices?.[0]?.delta?.content ?? "";
312	            } catch {
313	              continue;
314	            }
315	            if (!delta) continue;
316	            full += delta;
317	            buf += delta;
318	            setCaption(full);
319	            setTurns((prev) => prev.map((x) => (x.id === agentTurnId ? { ...x, text: full } : x)));
320	            let seg: [string, string] | null;
321	            while ((seg = nextClause(buf))) {
