329	        // aborted or network error — fall through to cleanup
330	      }
331	
332	      messagesRef.current.push({ role: "assistant", content: full });
333	      setTurns((prev) => prev.map((x) => (x.id === agentTurnId ? { ...x, live: false } : x)));
