335	      await chain; // wait until the last clause finishes speaking
336	      if (ac.signal.aborted) return;
337	      speakingRef.current = false;
338	      if (stateRef.current !== "ended") beginListening();
339	    },
340	    [beginListening, endListening, setState, speakClause],
341	  );
342	  onUserTurnRef.current = onUserTurn;
343	
344	  const start = useCallback(() => {
345	    if (stateRef.current !== "idle" && stateRef.current !== "ended") return;
346	    messagesRef.current = [];
347	    setTurns([]);
348	    setState("connecting");
349	    setCaption("connecting…");
350	
351	    // Bring up Mistral realtime STT in parallel with the opening line. The mic
