372	    stt.setMuted(mutedRef.current);
373	    sttRef.current = stt;
374	    stt.start().catch(() => {
375	      usingMistralRef.current = false;
376	    });
377	
378	    // Opening line: ask the LM for a greeting, then drop into listening.
379	    onUserTurn(agentRef.current.firstMessage);
380	  }, [onUserTurn, setState, startListening]);
381	
382	  const teardownStt = useCallback(() => {
383	    sttRef.current?.stop();
384	    sttRef.current = null;
385	    usingMistralRef.current = false;
386	  }, []);
387	
388	  const stop = useCallback(() => {
389	    abortRef.current?.abort();
390	    speakingRef.current = false;
391	    stopRecognition();
392	    teardownStt();
393	    currentAudioRef.current?.pause();
394	    if (typeof window !== "undefined") window.speechSynthesis?.cancel();
395	    setState("ended");
396	    setCaption("— call ended —");
397	  }, [setState, stopRecognition, teardownStt]);
398	
399	  const interrupt = useCallback(() => {
400	    if (stateRef.current !== "speaking") return;
401	    abortRef.current?.abort();
402	    currentAudioRef.current?.pause();
403	    if (typeof window !== "undefined") window.speechSynthesis?.cancel();
