407	  }, [beginListening, setState]);
408	
409	  // Manual end-of-turn ("send" button): end the current turn immediately instead
410	  // of waiting for the silence gate. For Web Speech, stop() forces a final result.
411	  const sendTurn = useCallback(() => {
412	    if (stateRef.current !== "listening") return;
413	    if (usingMistralRef.current && sttRef.current) sttRef.current.endTurnNow();
