415	  }, []);
416	
417	  const setMuted = useCallback((m: boolean) => {
418	    mutedRef.current = m;
419	    sttRef.current?.setMuted(m);
420	  }, []);
421	
422	  // Tear down when the engine is deselected or unmounted.
423	  useEffect(() => {
424	    if (active) return;
425	    return () => {
426	      abortRef.current?.abort();
427	      stopRecognition();
428	      teardownStt();
429	      currentAudioRef.current?.pause();
430	      if (typeof window !== "undefined") window.speechSynthesis?.cancel();
