1	"use client";
2	
3	// Browser-side leg of the Mistral realtime-STT cascade. Captures the mic at
4	// 16 kHz, streams PCM16 to the local proxy (which adds the Bearer header the
5	// browser can't), and turns Mistral's streaming `transcription.text.delta`
6	// events into discrete user turns.
7	//
8	// Turn boundaries are OURS, not the model's: Mistral only emits a terminal
9	// `transcription.done` after `input_audio.end` (which closes the stream), so for
10	// a back-and-forth conversation we keep the session open and detect end-of-turn
11	// client-side with **Silero VAD** (neural, via onnxruntime-web — see
12	// `silero-vad.ts`). Silero answers "did the user stop talking?"; Mistral answers
13	// "what did they say?". This replaced an energy/RMS gate that sat below most
14	// rooms' noise floor and never fired end-of-turn. The manual "send" button
15	// (`endTurnNow`) remains as an override.
16	//
17	// The proxy lives at NEXT_PUBLIC_MISTRAL_STT_WS (default ws://localhost:3001);
18	// run it with `mise run stt-proxy`. See scripts/mistral-stt-proxy.ts.
19	
20	import { calculateRms, float32ToPcm16Base64 } from "./xai-audio";
21	import { SileroVad } from "./silero-vad";
22	
23	const SAMPLE_RATE = 16000;
24	const PROC_FRAMES = 2048; // ~128 ms per audio block; a multiple of Silero's 512
25	const FLUSH_GRACE_MS = 350; // wait after flush to collect trailing deltas
26	// Silero turn-detection tunables (forwarded to SileroVad). Bump REDEMPTION_MS if
27	// it still ends turns too early; raise the thresholds if a noisy room over-triggers.
28	const VAD_REDEMPTION_MS = 900; // silence after speech that ends the turn
29	const VAD_MIN_SPEECH_MS = 250; // shortest run that counts as a real turn
30	const VAD_POSITIVE = 0.3; // speech-probability onset threshold
31	const VAD_NEGATIVE = 0.25; // speech-probability release threshold
32	
33	export interface MistralSttOptions {
34	  /** WebSocket URL of the local proxy (e.g. ws://localhost:3001). */
35	  wsUrl: string;
36	  /** Realtime transcription model id. */
37	  model?: string;
38	  /** Running transcript of the in-progress turn (drive the live caption). */
39	  onPartial: (text: string) => void;
40	  /** A completed user turn (silence detected after speech). */
41	  onFinal: (text: string) => void;
42	  /** Connected and configured — safe to start speaking. */
43	  onReady?: () => void;
44	  /** Fatal error (proxy down, mic denied, upstream closed). */
45	  onError?: (message: string) => void;
46	}
47	
48	export class MistralStt {
49	  private readonly opts: MistralSttOptions;
50	  private ws: WebSocket | null = null;
51	  private ctx: AudioContext | null = null;
52	  private stream: MediaStream | null = null;
53	  private source: MediaStreamAudioSourceNode | null = null;
54	  private proc: ScriptProcessorNode | null = null;
55	  private vad: SileroVad | null = null;
56	
57	  // Capture gating: audio is streamed only while listening && !muted.
58	  private listening = false;
59	  private muted = false;
60	  private closed = false;
61	  private ready = false;
62	
63	  // Per-turn transcript + emit state.
64	  private turnText = "";
65	  private emitting = false;
66	  private flushTimer: ReturnType<typeof setTimeout> | null = null;
67	  private inputRms = 0;
68	
69	  constructor(opts: MistralSttOptions) {
70	    this.opts = opts;
71	  }
72	
73	  /** Open the mic + proxy WebSocket and configure the session. Resolves once
74	   *  the audio graph and socket are wired (not necessarily server-ready). */
75	  async start(): Promise<void> {
76	    this.closed = false;
77	    const ctx = new AudioContext({ sampleRate: SAMPLE_RATE });
78	    this.ctx = ctx;
79	
80	    const stream = await navigator.mediaDevices.getUserMedia({
81	      audio: {
82	        channelCount: 1,
83	        echoCancellation: true,
84	        noiseSuppression: true,
85	        // AGC boosts ambient noise enough to trip the VAD — keep it off so the
86	        // silence gate stays stable (same lesson as the PersonaPlex mic gate).
87	        autoGainControl: false,
88	      },
89	    });
90	    if (this.closed) {
91	      stream.getTracks().forEach((t) => t.stop());
92	      return;
93	    }
94	    this.stream = stream;
95	    if (ctx.state === "suspended") await ctx.resume();
96	
97	    const source = ctx.createMediaStreamSource(stream);
98	    this.source = source;
99	    const proc = ctx.createScriptProcessor(PROC_FRAMES, 1, 1);
100	    this.proc = proc;
101	    proc.onaudioprocess = (e) => this.onAudio(e.inputBuffer.getChannelData(0));
102	    source.connect(proc);
103	    // Required for the callback to fire in some browsers; the node writes no
104	    // output, so this does not echo the mic to the speakers.
105	    proc.connect(ctx.destination);
106	
107	    this.connectWs();
108	
109	    // Load Silero VAD in parallel (model fetch + ORT init). The mic streams to
110	    // Mistral immediately; turn detection comes online once this resolves. If it
111	    // fails to load, transcription still works — the manual "send" button covers
112	    // turn ends.
113	    SileroVad.create({
114	      positiveSpeechThreshold: VAD_POSITIVE,
115	      negativeSpeechThreshold: VAD_NEGATIVE,
116	      redemptionMs: VAD_REDEMPTION_MS,
117	      minSpeechMs: VAD_MIN_SPEECH_MS,
118	      onSpeechStart: () => this.onSpeechStart(),
119	      onSpeechEnd: () => this.onSpeechEnd(),
120	      // VAD failure is non-fatal: don't tear down Mistral STT (and don't fall
121	      // back to Web Speech, which is the thing we moved away from) — just lose
122	      // auto turn-detection. The manual "send" button still ends turns.
123	      onError: (m) => console.warn(`[mistral-stt] VAD: ${m} — use the Send button`),
124	    })
125	      .then((vad) => {
126	        if (this.closed) {
127	          vad.close();
128	          return;
129	        }
130	        this.vad = vad;
131	        if (this.listening && !this.muted) vad.resume();
132	      })
133	      .catch((err) => {
134	        console.warn(
135	          `[mistral-stt] Silero VAD load failed (${err instanceof Error ? err.message : "unknown"}) — use the Send button`,
136	        );
137	      });
138	  }
139	
140	  private connectWs(): void {
141	    const model = this.opts.model ?? "voxtral-mini-transcribe-realtime-2602";
142	    const url = `${this.opts.wsUrl}?model=${encodeURIComponent(model)}`;
143	    let ws: WebSocket;
144	    try {
145	      ws = new WebSocket(url);
146	    } catch {
147	      this.opts.onError?.("STT proxy unreachable");
148	      return;
149	    }
150	    this.ws = ws;
151	    ws.onopen = () => {
152	      ws.send(
153	        JSON.stringify({
154	          type: "session.update",
155	          session: {
156	            audio_format: { encoding: "pcm_s16le", sample_rate: SAMPLE_RATE },
157	            target_streaming_delay_ms: 1000,
158	          },
159	        }),
160	      );
161	    };
162	    ws.onmessage = (ev) => this.onMessage(ev);
163	    ws.onerror = () => {
164	      if (!this.closed) this.opts.onError?.("STT proxy connection error");
165	    };
166	    ws.onclose = () => {
167	      if (!this.closed && this.ready) this.opts.onError?.("STT session closed");
168	    };
169	  }
170	
171	  private onMessage(ev: MessageEvent): void {
172	    let msg: { type?: string; text?: string };
173	    try {
174	      msg = JSON.parse(typeof ev.data === "string" ? ev.data : "{}");
175	    } catch {
176	      return;
177	    }
178	    switch (msg.type) {
179	      case "session.updated":
180	        if (!this.ready) {
181	          this.ready = true;
182	          this.opts.onReady?.();
183	        }
184	        break;
185	      case "transcription.text.delta":
186	        // Deltas only count toward a turn while we're actually listening; any
187	        // that arrive during the assistant's turn are dropped on resume.
188	        if (this.listening && !this.muted && msg.text) {
189	          this.turnText += msg.text;
190	          this.opts.onPartial(this.turnText.trim());
191	        }
192	        break;
193	      case "error":
194	        this.opts.onError?.("STT error");
195	        break;
196	      default:
197	        break;
198	    }
199	  }
200	
201	  private onAudio(input: Float32Array): void {
202	    if (this.muted || !this.listening) {
203	      this.inputRms = 0;
204	      return;
205	    }
206	    this.inputRms = calculateRms(input); // for the input-level visualizer only
207	
208	    const ws = this.ws;
209	    if (ws && ws.readyState === WebSocket.OPEN) {
210	      ws.send(JSON.stringify({ type: "input_audio.append", audio: float32ToPcm16Base64(input) }));
211	    }
212	
213	    // Silero decides the turn boundaries (onSpeechEnd → endTurn).
214	    this.vad?.feed(input);
215	  }
216	
217	  /** Silero saw speech begin. If an emit was pending (user paused, then resumed
218	   *  within the flush grace), cancel it and keep building the same turn. */
219	  private onSpeechStart(): void {
220	    if (this.emitting && this.flushTimer) {
221	      clearTimeout(this.flushTimer);
222	      this.flushTimer = null;
223	      this.emitting = false;
224	    }
225	  }
226	
227	  /** Silero saw end-of-speech ⇒ end the turn (flush + emit). */
228	  private onSpeechEnd(): void {
229	    if (this.listening && !this.muted && !this.emitting) this.endTurn();
230	  }
231	
232	  /** Manually end the current turn now (the "send" button), bypassing the
233	   *  silence gate. Flushes and emits whatever has been transcribed; no-op if not
234	   *  listening or already emitting. */
235	  endTurnNow(): void {
236	    if (!this.listening || this.muted || this.emitting) return;
237	    this.endTurn();
238	  }
239	
240	  /** Flush the tail, wait briefly for trailing deltas, then emit the turn. */
241	  private endTurn(): void {
242	    this.emitting = true;
243	    const ws = this.ws;
244	    if (ws && ws.readyState === WebSocket.OPEN) {
245	      ws.send(JSON.stringify({ type: "input_audio.flush" }));
246	    }
247	    if (this.flushTimer) clearTimeout(this.flushTimer);
248	    this.flushTimer = setTimeout(() => {
249	      const text = this.turnText.trim();
250	      this.resetTurn();
251	      this.emitting = false;
252	      if (text) this.opts.onFinal(text);
253	    }, FLUSH_GRACE_MS);
254	  }
255	
256	  private resetTurn(): void {
257	    this.turnText = "";
258	  }
259	
260	  /** Resume capturing the user (call when entering the listening state). */
261	  resume(): void {
262	    this.resetTurn();
263	    this.emitting = false;
264	    if (this.flushTimer) {
265	      clearTimeout(this.flushTimer);
266	      this.flushTimer = null;
267	    }
268	    this.listening = true;
269	    this.vad?.resume();
270	  }
271	
272	  /** Pause capturing (call while the assistant is speaking). Drops any
273	   *  half-formed turn so TTS bleed-through never becomes a user message. */
274	  pause(): void {
275	    this.listening = false;
276	    this.resetTurn();
277	    this.vad?.pause();
278	    if (this.flushTimer) {
279	      clearTimeout(this.flushTimer);
280	      this.flushTimer = null;
281	    }
282	  }
283	
284	  setMuted(muted: boolean): void {
285	    this.muted = muted;
286	  }
287	
288	  get isReady(): boolean {
289	    return this.ready;
290	  }
291	
292	  /** Current mic RMS (0 while paused/muted) for the input visualizer. */
293	  get level(): number {
294	    return this.inputRms;
295	  }
296	
297	  /** Tear everything down. */
298	  stop(): void {
299	    this.closed = true;
300	    this.listening = false;
301	    this.vad?.close();
302	    this.vad = null;
303	    if (this.flushTimer) {
304	      clearTimeout(this.flushTimer);
305	      this.flushTimer = null;
306	    }
307	    if (this.proc) {
308	      this.proc.onaudioprocess = null;
309	      try {
310	        this.proc.disconnect();
311	      } catch {
312	        // already disconnected
313	      }
314	      this.proc = null;
315	    }
316	    try {
317	      this.source?.disconnect();
318	    } catch {
319	      // already disconnected
320	    }
321	    this.source = null;
322	    this.stream?.getTracks().forEach((t) => t.stop());
323	    this.stream = null;
324	    if (this.ws) {
325	      const ws = this.ws;
326	      this.ws = null;
327	      try {
328	        if (ws.readyState === WebSocket.OPEN) ws.send(JSON.stringify({ type: "input_audio.end" }));
329	        ws.close();
330	      } catch {
331	        // already closing
332	      }
333	    }
334	    const ctx = this.ctx;
335	    this.ctx = null;
336	    if (ctx && ctx.state !== "closed") void ctx.close().catch(() => {});
337	  }
338	}
