1	// Standalone Bun WebSocket proxy for Mistral realtime transcription.
2	//
3	// Why this exists: Mistral's realtime-STT endpoint authenticates with an
4	// `Authorization: Bearer` header on the WebSocket *handshake* (the Python SDK
5	// sets it via `websockets.connect(..., additional_headers=...)`). The browser
6	// `WebSocket` constructor cannot set request headers, so the browser can't
7	// connect directly. This proxy bridges the gap:
8	//
9	//   browser ──ws(no auth)──▶ this proxy ──wss(Bearer header)──▶ api.mistral.ai
10	//
11	// It is a dumb pipe: every text/binary frame is forwarded verbatim in both
12	// directions. The only thing it adds is the auth header (and the upstream URL),
13	// so MISTRAL_API_KEY never reaches the client. Bun's `WebSocket` client accepts
14	// a `headers` option — the piece a browser lacks.
15	//
16	// Dev only. Run with secrets loaded: `fnox exec -- bun run scripts/mistral-stt-proxy.ts`
17	// (or `mise run stt-proxy`). Port via STT_PROXY_PORT (default 3001).
18	
19	const UPSTREAM_BASE = "wss://api.mistral.ai/v1/audio/transcriptions/realtime";
20	const DEFAULT_MODEL = "voxtral-mini-transcribe-realtime-2602";
21	const PORT = Number(process.env.STT_PROXY_PORT ?? 3001);
22	
23	const API_KEY = process.env.MISTRAL_API_KEY;
24	if (!API_KEY) {
25	  console.error(
26	    "[stt-proxy] MISTRAL_API_KEY is not set. Run via `fnox exec -- bun run scripts/mistral-stt-proxy.ts`.",
27	  );
28	  process.exit(1);
29	}
30	
31	// Per-connection state hung off the ServerWebSocket.
32	interface ProxyData {
33	  upstream: WebSocket | null;
34	  // Frames received from the browser before the upstream socket is open.
35	  pending: Array<string | ArrayBufferLike>;
36	  closed: boolean;
37	}
38	
39	const server = Bun.serve<ProxyData, undefined>({
40	  port: PORT,
41	  fetch(req, srv) {
42	    const url = new URL(req.url);
43	    if (url.pathname === "/health") {
44	      return new Response("ok", { status: 200 });
45	    }
46	    // Forward the model query param through to Mistral (default if absent).
47	    const model = url.searchParams.get("model") ?? DEFAULT_MODEL;
48	    const upgraded = srv.upgrade(req, {
49	      data: { upstream: null, pending: [], closed: false, model } as ProxyData & { model: string },
50	    });
51	    if (upgraded) return undefined;
52	    return new Response("This endpoint speaks WebSocket only.", { status: 426 });
53	  },
54	  websocket: {
55	    open(ws) {
56	      const data = ws.data as ProxyData & { model: string };
57	      const upstreamUrl = `${UPSTREAM_BASE}?model=${encodeURIComponent(data.model)}`;
58	      const upstream = new WebSocket(upstreamUrl, {
59	        headers: { Authorization: `Bearer ${API_KEY}` },
60	      } as unknown as string[]);
61	      upstream.binaryType = "arraybuffer";
62	      data.upstream = upstream;
63	
64	      upstream.addEventListener("open", () => {
65	        for (const frame of data.pending) upstream.send(frame);
66	        data.pending = [];
67	      });
68	      upstream.addEventListener("message", (ev: MessageEvent) => {
69	        if (data.closed) return;
70	        ws.send(ev.data as string | ArrayBufferLike);
71	      });
72	      upstream.addEventListener("close", (ev: CloseEvent) => {
73	        if (!data.closed) ws.close(ev.code === 1006 ? 1011 : ev.code, ev.reason);
74	      });
75	      upstream.addEventListener("error", () => {
76	        if (!data.closed) ws.close(1011, "upstream error");
77	      });
78	    },
79	    message(ws, message) {
80	      const data = ws.data as ProxyData;
81	      const up = data.upstream;
82	      const frame = typeof message === "string" ? message : (message as Uint8Array).buffer;
83	      if (up && up.readyState === WebSocket.OPEN) up.send(frame);
84	      else data.pending.push(frame);
85	    },
86	    close(ws) {
87	      const data = ws.data as ProxyData;
88	      data.closed = true;
89	      try {
90	        data.upstream?.close();
91	      } catch {
92	        // already closing
93	      }
94	    },
95	  },
96	});
97	
98	console.log(
99	  `[stt-proxy] listening on ws://localhost:${server.port}  →  ${UPSTREAM_BASE} (default model ${DEFAULT_MODEL})`,
100	);
