1	// Server-side LM stage for the STT → LM → TTS cascade engine.
2	//
3	// Streams an OpenAI-compatible chat completion from a backend chosen per request,
4	// so the cascade can swap LMs without the browser ever seeing a key. Backends and
5	// their URL + secret env key are defined in `config/lm-models.json` (the model
6	// catalog) — add one there, not here. The upstream SSE body is piped straight back
7	// to the client, which reads the `data: {...}` deltas. Reasoning models stream
8	// chain-of-thought in a separate field and emit no spoken `content` until thinking
9	// ends, so for backends with `supportsThinking` we send
10	// `chat_template_kwargs.enable_thinking:false` by default.
11	//
12	// Dev only: the secret named by each backend's `envKey` (HF_TOKEN / MISTRAL_API_KEY)
13	// is provided via fnox (`fnox exec -- bun run dev`).
14	
15	import { DEFAULT_LM_MODEL, resolveLmBackend } from "@/lib/realtime/lm-config";
16	
17	export const runtime = "nodejs";
18	export const dynamic = "force-dynamic";
19	
20	interface LlmRequest {
21	  /** Backend id from the catalog (a key of `backends` in config/lm-models.json). */
22	  backend?: string;
23	  model?: string;
24	  messages?: Array<{ role: string; content: string }>;
25	  maxTokens?: number;
26	  temperature?: number;
27	  enableThinking?: boolean;
28	}
29	
30	export async function POST(req: Request): Promise<Response> {
31	  let body: LlmRequest;
32	  try {
33	    body = (await req.json()) as LlmRequest;
34	  } catch {
35	    return Response.json({ error: "Invalid JSON body." }, { status: 400 });
36	  }
37	
38	  const backendId = body.backend ?? DEFAULT_LM_MODEL.backend;
39	  const backend = resolveLmBackend(backendId);
40	  if (!backend) {
41	    return Response.json(
42	      { error: `Unknown LM backend "${backendId}" (define it in config/lm-models.json).` },
43	      { status: 400 },
44	    );
45	  }
46	  const apiKey = REDACTED;
47	  if (!apiKey) {
48	    return Response.json(
49	      { error: `${backend.envKey} is not set on the server (provide it via fnox).` },
50	      { status: 500 },
51	    );
52	  }
53	  if (!body.model || !Array.isArray(body.messages) || body.messages.length === 0) {
54	    return Response.json({ error: "model and messages are required." }, { status: 400 });
55	  }
56	
57	  const upstreamBody: Record<string, unknown> = {
58	    model: body.model,
59	    messages: body.messages,
60	    stream: true,
61	    max_tokens: body.maxTokens ?? 256,
62	    temperature: body.temperature ?? 0.7,
63	  };
64	  // Reasoning models toggle chain-of-thought via chat_template_kwargs (ignored by
65	  // non-reasoning models). APIs that reject unknown fields (e.g. Mistral, 422) set
66	  // supportsThinking:false in the catalog, so we only send it where it's accepted.
67	  if (backend.supportsThinking) {
68	    upstreamBody.chat_template_kwargs = { enable_thinking: body.enableThinking ?? false };
69	  }
70	
71	  let upstream: Response;
72	  try {
73	    upstream = await fetch(backend.url, {
74	      method: "POST",
75	      headers: {
76	        Authorization: `Bearer ${apiKey}`,
77	        "Content-Type": "application/json",
78	        Accept: "text/event-stream",
79	      },
80	      body: JSON.stringify(upstreamBody),
81	    });
82	  } catch (err) {
83	    return Response.json(
84	      {
85	        error: `Failed to reach ${backendId}: ${err instanceof Error ? err.message : "network error"}`,
86	      },
87	      { status: 502 },
88	    );
89	  }
90	
91	  if (!upstream.ok || !upstream.body) {
92	    const detail = await upstream.text().catch(() => "");
93	    return Response.json(
94	      { error: `${backendId} chat completion failed`, status: upstream.status, detail },
95	      { status: 502 },
96	    );
97	  }
98	
99	  // Pipe the upstream SSE straight to the client.
100	  return new Response(upstream.body, {
101	    status: 200,
102	    headers: {
103	      "Content-Type": "text/event-stream; charset=utf-8",
104	      "Cache-Control": "no-store",
105	      Connection: "keep-alive",
106	    },
107	  });
108	}
