56	  onerror: ((e: { error?: string }) => void) | null;
57	}
58	type SpeechRecognitionCtor = new () => SpeechRecognitionLike;
59	
60	function getRecognitionCtor(): SpeechRecognitionCtor | null {
61	  if (typeof window === "undefined") return null;
62	  const w = window as unknown as {
63	    SpeechRecognition?: SpeechRecognitionCtor;
64	    webkitSpeechRecognition?: SpeechRecognitionCtor;
65	  };
66	  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
67	}
68	
69	// Segment a streamed token buffer into speakable clauses (sentence end, or a
70	// clause break once long enough) so TTS starts on the first clause.
71	const SENTENCE_END = /[.!?](?=\s|$)/;
72	const CLAUSE_BREAK = /[,;:](?=\s)/;
73	const MIN_CLAUSE = 30;
74	
75	function nextClause(buf: string): [string, string] | null {
76	  const end = buf.match(SENTENCE_END);
77	  if (end && end.index != null) {
78	    const cut = end.index + 1;
79	    return [buf.slice(0, cut).trim(), buf.slice(cut)];
80	  }
81	  if (buf.length >= MIN_CLAUSE) {
82	    const c = buf.match(CLAUSE_BREAK);
83	    if (c && c.index != null) {
84	      const cut = c.index + 1;
85	      return [buf.slice(0, cut).trim(), buf.slice(cut)];
86	    }
87	  }
88	  return null;
89	}
90	
91	export function useCascadeSession(
92	  active: boolean,
93	  persona?: Persona,
94	  lmModelId?: string,
95	): CascadeSession {
96	  const [callState, setCallState] = useState<CallState>("idle");
97	  const [turns, setTurns] = useState<SessionTurn[]>([]);
98	  const [caption, setCaption] = useState("press CALL to begin");
99	
100	  // Re-resolves when the persona or the picked LM model changes; agentRef is
101	  // updated every render, so a model switch applies on the next turn.
102	  const agent = useMemo(
103	    () => resolveCascadeAgent(persona?.id, lmModelId),
104	    [persona?.id, lmModelId],
105	  );
106	  const agentRef = useRef(agent);
107	  agentRef.current = agent;
108	
109	  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
110	  // Mistral realtime STT (preferred). Falls back to Web Speech if the proxy or
111	  // mic is unavailable, in which case usingMistralRef flips to false.
112	  const sttRef = useRef<MistralStt | null>(null);
113	  const usingMistralRef = useRef(false);
114	  const messagesRef = useRef<Array<{ role: string; content: string }>>([]);
115	  const mutedRef = useRef(false);
116	  const speakingRef = useRef(false);
117	  const abortRef = useRef<AbortController | null>(null);
118	  const liveTurnId = useRef<string | null>(null);
119	  const currentAudioRef = useRef<HTMLAudioElement | null>(null);
120	  // Breaks the startListening ↔ onUserTurn recursion (each is declared before
121	  // the other needs it); startListening calls through the ref.
122	  const onUserTurnRef = useRef<(t: string) => void>(() => {});
123	
124	  const stateRef = useRef<CallState>("idle");
125	  const setState = useCallback((s: CallState) => {
126	    stateRef.current = s;
127	    setCallState(s);
128	  }, []);
129	
130	  const stopRecognition = useCallback(() => {
131	    const rec = recognitionRef.current;
132	    if (rec) {
133	      rec.onend = null;
134	      try {
135	        rec.abort();
136	      } catch {
137	        // already stopped
138	      }
139	    }
140	  }, []);
141	
142	  const startListening = useCallback(() => {
143	    const Ctor = getRecognitionCtor();
144	    if (!Ctor) {
145	      setCaption("— speech recognition unavailable (use Chrome) —");
146	      return;
147	    }
148	    const rec = new Ctor();
149	    rec.lang = "en-US";
150	    rec.continuous = true;
151	    rec.interimResults = true;
152	    rec.onresult = (e) => {
153	      if (speakingRef.current || mutedRef.current) return;
154	      let interim = "";
155	      let finalText = "";
156	      for (let i = e.resultIndex; i < e.results.length; i++) {
157	        const r = e.results[i];
158	        if (r.isFinal) finalText += r[0].transcript;
159	        else interim += r[0].transcript;
160	      }
161	      if (interim) setCaption(interim);
162	      if (finalText.trim()) onUserTurnRef.current(finalText.trim());
163	    };
164	    rec.onerror = () => {};
165	    // Chrome stops recognition on silence; restart it while we're still listening.
166	    rec.onend = () => {
167	      if (stateRef.current === "listening" && !speakingRef.current) {
168	        try {
169	          rec.start();
170	        } catch {
171	          // start() throws if already running; ignore
172	        }
173	      }
174	    };
175	    recognitionRef.current = rec;
176	    try {
177	      rec.start();
178	    } catch {
179	      // ignore double-start
180	    }
181	    setState("listening");
182	  }, [setState]);
183	
184	  // Enter the listening state on whichever STT path is active: resume the open
185	  // Mistral session, or (fallback) (re)start Web Speech.
186	  const beginListening = useCallback(() => {
187	    if (usingMistralRef.current && sttRef.current) {
188	      sttRef.current.resume();
189	      setCaption("listening…");
190	      setState("listening");
191	      return;
192	    }
193	    startListening();
194	  }, [setState, startListening]);
195	
196	  // Leave the listening state (assistant about to speak): pause the Mistral
197	  // session, or stop Web Speech.
198	  const endListening = useCallback(() => {
199	    if (usingMistralRef.current && sttRef.current) {
200	      sttRef.current.pause();
201	      return;
202	    }
203	    stopRecognition();
204	  }, [stopRecognition]);
205	
206	  // Browser speechSynthesis fallback (used when the Mistral TTS route fails).
207	  const speakBrowser = useCallback((text: string): Promise<void> => {
208	    return new Promise((resolve) => {
209	      if (typeof window === "undefined" || !window.speechSynthesis) {
210	        resolve();
211	        return;
212	      }
213	      const u = new SpeechSynthesisUtterance(text);
214	      u.onend = () => resolve();
215	      u.onerror = () => resolve();
216	      window.speechSynthesis.speak(u);
217	    });
218	  }, []);
219	
220	  // Speak one clause via Mistral TTS; resolves when playback finishes. Falls back
221	  // to browser speechSynthesis if the route/key is unavailable.
222	  const speakClause = useCallback(
223	    async (text: string, signal: AbortSignal): Promise<void> => {
224	      try {
225	        const res = await fetch("/api/mistral/tts", {
226	          method: "POST",
227	          headers: { "Content-Type": "application/json" },
228	          body: JSON.stringify({ text, voice: agentRef.current.ttsVoice }),
229	          signal,
230	        });
231	        if (!res.ok) throw new Error("tts");
232	        const blob = await res.blob();
233	        if (signal.aborted) return;
234	        const url = URL.createObjectURL(blob);
235	        const audio = new Audio(url);
236	        currentAudioRef.current = audio;
237	        await new Promise<void>((resolve) => {
238	          audio.onended = () => resolve();
239	          audio.onerror = () => resolve();
240	          void audio.play().catch(() => resolve());
241	        });
242	        URL.revokeObjectURL(url);
243	        if (currentAudioRef.current === audio) currentAudioRef.current = null;
244	      } catch {
245	        if (!signal.aborted) await speakBrowser(text);
246	      }
247	    },
248	    [speakBrowser],
249	  );
250	
251	  // Run one assistant turn: stream the LM reply and speak it clause by clause.
252	  // `visible: false` keeps the user text out of the transcript — the greeting
253	  // bootstrap is an internal instruction to the LM, not something the user said.
254	  const onUserTurn = useCallback(
255	    async (userText: string, { visible = true } = {}) => {
256	      endListening();
257	      speakingRef.current = true;
258	      if (visible) {
259	        setTurns((prev) => [...prev, { id: `u${prev.length}`, who: "user", text: userText }]);
260	      }
261	      messagesRef.current.push({ role: "user", content: userText });
262	      setState("speaking");
263	
264	      const a = agentRef.current;
265	      const agentTurnId = `a${Date.now()}`;
266	      liveTurnId.current = agentTurnId;
267	      setTurns((prev) => [...prev, { id: agentTurnId, who: "agent", text: "", live: true }]);
268	
269	      abortRef.current?.abort();
270	      const ac = new AbortController();
271	      abortRef.current = ac;
272	
273	      let buf = "";
274	      let full = "";
275	      const speakQueue: Promise<void> = Promise.resolve();
276	      let chain = speakQueue;
277	
278	      const enqueue = (clause: string) => {
279	        chain = chain.then(() => (ac.signal.aborted ? undefined : speakClause(clause, ac.signal)));
280	      };
281	
282	      try {
283	        const res = await fetch("/api/llm", {
284	          method: "POST",
285	          headers: { "Content-Type": "application/json" },
286	          body: JSON.stringify({
287	            backend: a.lmBackend,
288	            model: a.lmModel,
289	            messages: [{ role: "system", content: a.instructions }, ...messagesRef.current],
290	            maxTokens: a.maxTokens,
291	            temperature: a.temperature,
292	          }),
293	          signal: ac.signal,
294	        });
295	        if (!res.ok || !res.body) {
296	          setCaption("— LM error —");
297	          throw new Error("llm");
298	        }
299	        const reader = res.body.getReader();
300	        const decoder = new TextDecoder();
301	        let sse = "";
302	        while (true) {
303	          const { done, value } = await reader.read();
304	          if (done) break;
305	          sse += decoder.decode(value, { stream: true });
306	          const lines = sse.split("\n");
307	          sse = lines.pop() ?? "";
308	          for (const line of lines) {
309	            const t = line.trim();
310	            if (!t.startsWith("data:")) continue;
311	            const data = t.slice(5).trim();
312	            if (data === "[DONE]") continue;
313	            let delta = "";
314	            try {
315	              delta = JSON.parse(data)?.choices?.[0]?.delta?.content ?? "";
316	            } catch {
317	              continue;
318	            }
319	            if (!delta) continue;
320	            full += delta;
321	            buf += delta;
322	            setCaption(full);
323	            setTurns((prev) => prev.map((x) => (x.id === agentTurnId ? { ...x, text: full } : x)));
324	            let seg: [string, string] | null;
325	            while ((seg = nextClause(buf))) {
326	              if (seg[0]) enqueue(seg[0]);
327	              buf = seg[1];
328	            }
329	          }
330	        }
331	        if (buf.trim()) enqueue(buf.trim());
332	      } catch {
333	        // aborted or network error — fall through to cleanup
334	      }
335	
336	      messagesRef.current.push({ role: "assistant", content: full });
337	      setTurns((prev) => prev.map((x) => (x.id === agentTurnId ? { ...x, live: false } : x)));
338	
339	      await chain; // wait until the last clause finishes speaking
340	      if (ac.signal.aborted) return;
341	      speakingRef.current = false;
342	      if (stateRef.current !== "ended") beginListening();
343	    },
344	    [beginListening, endListening, setState, speakClause],
345	  );
346	  onUserTurnRef.current = onUserTurn;
347	
348	  const teardownStt = useCallback(() => {
349	    sttRef.current?.stop();
350	    sttRef.current = null;
351	    usingMistralRef.current = false;
352	  }, []);
353	
354	  // Full hang-up: abort the in-flight LM turn and silence every audio path.
355	  const teardown = useCallback(() => {
356	    abortRef.current?.abort();
357	    speakingRef.current = false;
358	    stopRecognition();
359	    teardownStt();
360	    currentAudioRef.current?.pause();
361	    if (typeof window !== "undefined") window.speechSynthesis?.cancel();
362	  }, [stopRecognition, teardownStt]);
363	
364	  const start = useCallback(() => {
365	    if (stateRef.current !== "idle" && stateRef.current !== "ended") return;
366	    messagesRef.current = [];
367	    setTurns([]);
368	    setState("connecting");
369	    setCaption("connecting…");
370	
371	    // Bring up Mistral realtime STT in parallel with the opening line. The mic
372	    // stays paused (endListening on the greeting turn) until the greeting
373	    // finishes and beginListening() resumes it.
374	    usingMistralRef.current = true;
375	    const stt = new MistralStt({
376	      wsUrl: STT_WS_URL,
377	      onPartial: (text) => {
378	        if (stateRef.current === "listening") setCaption(text);
379	      },
380	      onFinal: (text) => {
381	        if (!speakingRef.current && !mutedRef.current) onUserTurnRef.current(text);
382	      },
383	      onError: () => {
384	        // Shut down the failed Mistral leg (mic stream, AudioContext, VAD,
385	        // socket) before dropping to the browser Web Speech fallback —
386	        // otherwise both capture paths run side by side for the rest of the call.
387	        teardownStt();
388	        if (stateRef.current === "listening") {
389	          setCaption("— STT proxy unavailable, using browser speech —");
390	          startListening();
391	        }
392	      },
393	    });
394	    stt.setMuted(mutedRef.current);
395	    sttRef.current = stt;
396	    stt.start().catch(() => {
397	      // Mic denied / AudioContext failure: release whatever start() got to.
398	      teardownStt();
399	    });
400	
401	    // Opening line: ask the LM for a greeting, then drop into listening. The
402	    // elicitation prompt goes to the LM only — never into the visible transcript.
403	    onUserTurn(agentRef.current.firstMessage, { visible: false });
404	  }, [onUserTurn, setState, startListening, teardownStt]);
405	
406	  const stop = useCallback(() => {
407	    teardown();
408	    setState("ended");
409	    setCaption("— call ended —");
410	  }, [setState, teardown]);
411	
412	  const interrupt = useCallback(() => {
413	    if (stateRef.current !== "speaking") return;
414	    abortRef.current?.abort();
415	    currentAudioRef.current?.pause();
416	    if (typeof window !== "undefined") window.speechSynthesis?.cancel();
417	    speakingRef.current = false;
418	    setState("interrupted");
419	    beginListening();
420	  }, [beginListening, setState]);
421	
422	  // Manual end-of-turn ("send" button): end the current turn immediately instead
423	  // of waiting for the silence gate. For Web Speech, stop() forces a final result.
424	  const sendTurn = useCallback(() => {
425	    if (stateRef.current !== "listening") return;
426	    if (usingMistralRef.current && sttRef.current) sttRef.current.endTurnNow();
427	    else recognitionRef.current?.stop();
428	  }, []);
429	
430	  const setMuted = useCallback((m: boolean) => {
431	    mutedRef.current = m;
432	    sttRef.current?.setMuted(m);
433	  }, []);
434	
435	  // Hang up + reset if the engine is deselected mid-session. Teardown must run
436	  // directly in the !active branch (same as the xAI/OpenAI hooks) — a cleanup
437	  // returned here would only fire on the *next* deps change or unmount, leaving
438	  // the mic and STT socket live after a provider switch.
439	  useEffect(() => {
440	    if (active || stateRef.current === "idle") return;
441	    teardown();
442	    setState("idle");
443	    setTurns([]);
444	    setCaption("press CALL to begin");
445	  }, [active, setState, teardown]);
446	
447	  // Cleanup on unmount.
448	  useEffect(() => () => teardown(), [teardown]);
449	
450	  const getInputVolume = useCallback(() => {
451	    const s = stateRef.current;
452	    // Real mic RMS when Mistral STT is driving; otherwise a synthetic pulse
453	    // (Web Speech exposes no level).
454	    if (usingMistralRef.current && sttRef.current && (s === "listening" || s === "interrupted")) {
455	      return Math.min(1, 0.06 + sttRef.current.level * 6);
456	    }
457	    if (s === "listening" || s === "interrupted")
458	      return 0.25 + 0.4 * Math.abs(Math.sin(performance.now() / 180));
459	    return 0.04;
460	  }, []);
461	  const getOutputVolume = useCallback(() => {
462	    if (stateRef.current === "speaking")
463	      return 0.4 + 0.45 * Math.abs(Math.sin(performance.now() / 140));
464	    return 0.04;
465	  }, []);
466	
467	  return useMemo<CascadeSession>(
468	    () => ({
469	      callState,
470	      turns,
471	      caption,
472	      start,
473	      stop,
474	      interrupt,
475	      sendTurn,
476	      setMuted,
477	      getInputVolume,
478	      getOutputVolume,
479	    }),
480	    [
481	      callState,
482	      turns,
483	      caption,
484	      start,
485	      stop,
486	      interrupt,
487	      sendTurn,
488	      setMuted,
489	      getInputVolume,
490	      getOutputVolume,
491	    ],
492	  );
493	}
