// Catalog of TTS + STT backends for the cascade engine's voice legs.
//
// Mirrors lm-config.ts: the data lives in `config/voice-models.json`, read by
// both the server routes (`app/api/tts`, `app/api/stt` — which resolve a
// backend's URL + secret env key) and the client session (which picks the
// backend id and the STT capture mode). Only env var *names* and public URLs
// live here; secret values stay in fnox and are read server-side. An empty
// `envKey` marks a keyless local backend (mlx-audio server via
// `mise run audio-local`).
//
// The default backend per leg comes from the catalog, overridable per
// dev-session with NEXT_PUBLIC_TTS_BACKEND / NEXT_PUBLIC_STT_BACKEND — so
// flipping a leg cloud ↔ local is an env var, not a config edit.

import catalog from "@/config/voice-models.json";

export interface TtsBackendConfig {
  /** Speech endpoint (Mistral /v1/audio/speech or an OpenAI-style local one). */
  url: string;
  /** Secret env var name (server-side only). Empty = keyless local backend. */
  envKey: string;
  /** Upstream TTS model id. */
  model: string;
  /** How the upstream returns audio: `mistral-json` = {audio_data: base64};
   *  `audio-bytes` = raw audio body (OpenAI-style). */
  responseShape: "mistral-json" | "audio-bytes";
  /** Sampling temperature (local voxtral_tts: ~0.5 tightens pauses). */
  temperature?: number;
  /** Fallback voice when a slug has no `voiceMap` entry. */
  defaultVoice?: string;
  /** Mistral voice_id slug → this backend's preset name. Lets cascade-agent
   *  keep one `ttsVoice` string per persona across backends. */
  voiceMap?: Record<string, string>;
}

export interface SttBackendConfig {
  /** `realtime` = Mistral WS via the Bun proxy; `batch` = per-turn POST of the
   *  finished turn's WAV to /api/stt (Silero VAD still owns the boundaries). */
  mode: "realtime" | "batch";
  /** Batch transcription endpoint (unused for `realtime`). */
  url?: string;
  /** Secret env var name (server-side only). Empty/absent = keyless. */
  envKey?: string;
  /** Upstream STT model id (batch mode). */
  model?: string;
}

interface VoiceCatalog {
  tts: { default: string; backends: Record<string, TtsBackendConfig> };
  stt: { default: string; backends: Record<string, SttBackendConfig> };
}

const CONFIG = catalog as unknown as VoiceCatalog;

/** Look up a TTS backend by id, falling back to the catalog default. */
export function resolveTtsBackend(id?: string): TtsBackendConfig | undefined {
  return CONFIG.tts.backends[id || CONFIG.tts.default];
}

/** Look up an STT backend by id, falling back to the catalog default. */
export function resolveSttBackend(id?: string): SttBackendConfig | undefined {
  return CONFIG.stt.backends[id || CONFIG.stt.default];
}

/** Backend id each leg uses this session: env override > catalog default. */
export const DEFAULT_TTS_BACKEND_ID: string =
  process.env.NEXT_PUBLIC_TTS_BACKEND || CONFIG.tts.default;
export const DEFAULT_STT_BACKEND_ID: string =
  process.env.NEXT_PUBLIC_STT_BACKEND || CONFIG.stt.default;

// Text-to-speech for the cascade engine's TTS leg, catalog-driven like /api/llm.
//
// POST { text, voice, backend? } → resolves a backend from
// config/voice-models.json (Mistral cloud or the local mlx-audio server) and
// returns audio/mpeg bytes the browser can play as a blob. Secrets stay
// server-side (fnox); a backend with an empty envKey is keyless (local).
//
// `voice` is always a Mistral voice_id slug (cascade-agent's ttsVoice); a
// backend with a `voiceMap` translates it to its own preset names, so persona
// voices are cast per backend in the catalog, not in code.
//
// Response shapes: Mistral answers `{ audio_data: <base64> }` (mistral-json);
// an OpenAI-style server streams raw audio bytes (audio-bytes). Per-clause
// calls keep each request short so playback pipelines with the LM stream.

import { DEFAULT_TTS_BACKEND_ID, resolveTtsBackend } from "@/lib/realtime/voice-config";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

interface TtsRequest {
  text?: string;
  voice?: string;
  /** Backend id from config/voice-models.json (defaults to the catalog default). */
  backend?: string;
}

const DEFAULT_VOICE = "en_paul_neutral";

export async function POST(req: Request): Promise<Response> {
  let body: TtsRequest;
  try {
    body = (await req.json()) as TtsRequest;
  } catch {
    return Response.json({ error: "Invalid JSON body." }, { status: 400 });
  }
  const text = body.text?.trim();
  if (!text) return Response.json({ error: "text is required." }, { status: 400 });

  const backendId = body.backend || DEFAULT_TTS_BACKEND_ID;
  const backend = resolveTtsBackend(backendId);
  if (!backend) {
    return Response.json(
      { error: `Unknown TTS backend "${backendId}" (define it in config/voice-models.json).` },
      { status: 400 },
    );
  }
  const apiKey = REDACTED ? process.env[backend.envKey] : undefined;
  if (backend.envKey && !apiKey) {
    return Response.json(
      { error: `${backend.envKey} is not set on the server (provide it via fnox).` },
      { status: 500 },
    );
  }

  // Translate the Mistral voice_id slug into this backend's voice name.
  const slug = body.voice || DEFAULT_VOICE;
  const voice = backend.voiceMap ? (backend.voiceMap[slug] ?? backend.defaultVoice ?? slug) : slug;

  const upstreamBody: Record<string, unknown> = {
    model: backend.model,
    input: text,
    response_format: "mp3",
  };
  if (backend.responseShape === "mistral-json") {
    upstreamBody.voice_id = voice;
  } else {
    upstreamBody.voice = voice;
    if (backend.temperature != null) upstreamBody.temperature = backend.temperature;
  }

  let upstream: Response;
  try {
    upstream = await fetch(backend.url, {
      method: "POST",
      headers: {
        ...(apiKey ? { Authorization: `Bearer ${apiKey}` } : {}),
        "Content-Type": "application/json",
      },
      body: JSON.stringify(upstreamBody),
    });
  } catch (err) {
    return Response.json(
      {
        error: `Failed to reach ${backendId}: ${err instanceof Error ? err.message : "network error"}`,
      },
      { status: 502 },
    );
  }

  if (!upstream.ok) {
    const detail = await upstream.text().catch(() => "");
    return Response.json(
      { error: `${backendId} speech request failed`, status: upstream.status, detail },
      { status: 502 },
    );
  }

  const headers = { "Content-Type": "audio/mpeg", "Cache-Control": "no-store" };

  // OpenAI-style backends stream the audio body directly — pipe it through.
  if (backend.responseShape === "audio-bytes") {
    return new Response(upstream.body, { status: 200, headers });
  }

  const json = (await upstream.json()) as { audio_data?: string };
  if (!json.audio_data) {
    return Response.json({ error: `${backendId} returned no audio_data.` }, { status: 502 });
  }
  return new Response(Buffer.from(json.audio_data, "base64"), { status: 200, headers });
}

// Batch speech-to-text for the cascade engine's local STT leg.
//
// POST (body = a finished turn's WAV bytes, `?backend=` a catalog id) →
// forwards the audio as multipart form-data to the backend's transcription
// endpoint (the local mlx-audio server's OpenAI-compatible
// /v1/audio/transcriptions) and returns `{ text }`.
//
// This is the batch alternative to the Mistral realtime WS (which streams
// partial captions): Silero VAD already owns turn boundaries client-side, so
// the client simply records each turn's PCM and posts it here on turn end.
// See docs/voxtral-local-inference.md (STT leg, option b).

import { DEFAULT_STT_BACKEND_ID, resolveSttBackend } from "@/lib/realtime/voice-config";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function POST(req: Request): Promise<Response> {
  const backendId = new URL(req.url).searchParams.get("backend") || DEFAULT_STT_BACKEND_ID;
  const backend = resolveSttBackend(backendId);
  if (!backend || backend.mode !== "batch" || !backend.url || !backend.model) {
    return Response.json(
      { error: `"${backendId}" is not a batch STT backend (see config/voice-models.json).` },
      { status: 400 },
    );
  }
  const apiKey = REDACTED ? process.env[backend.envKey] : undefined;
  if (backend.envKey && !apiKey) {
    return Response.json(
      { error: `${backend.envKey} is not set on the server (provide it via fnox).` },
      { status: 500 },
    );
  }

  const audio = await req.arrayBuffer();
  if (audio.byteLength === 0) {
    return Response.json({ error: "empty audio body." }, { status: 400 });
  }

  const form = new FormData();
  form.append("file", new Blob([audio], { type: "audio/wav" }), "turn.wav");
  form.append("model", backend.model);
  form.append("response_format", "json");

  let upstream: Response;
  try {
    upstream = await fetch(backend.url, {
      method: "POST",
      headers: apiKey ? { Authorization: `Bearer ${apiKey}` } : undefined,
      body: form,
    });
  } catch (err) {
    return Response.json(
      {
        error: `Failed to reach ${backendId}: ${err instanceof Error ? err.message : "network error"}`,
      },
      { status: 502 },
    );
  }

  if (!upstream.ok) {
    const detail = await upstream.text().catch(() => "");
    return Response.json(
      { error: `${backendId} transcription failed`, status: upstream.status, detail },
      { status: 502 },
    );
  }

  const json = (await upstream.json().catch(() => null)) as { text?: string } | null;
  if (!json || typeof json.text !== "string") {
    return Response.json({ error: `${backendId} returned no text.` }, { status: 502 });
  }
  return Response.json({ text: json.text.trim() });
}

// Minimal WAV (RIFF/PCM16) encoder for posting a recorded turn to /api/stt.
// Mono, little-endian; the sample rate is whatever the capture context runs at
// (the cascade records at 16 kHz for Voxtral).

/** Encode Float32 [-1, 1] chunks as a mono PCM16 WAV file. */
export function encodeWavPcm16(chunks: Float32Array[], sampleRate: number): Blob {
  const frames = chunks.reduce((n, c) => n + c.length, 0);
  const dataSize = frames * 2;
  const buf = new ArrayBuffer(44 + dataSize);
  const view = new DataView(buf);

  const writeAscii = (offset: number, s: string) => {
    for (let i = 0; i < s.length; i++) view.setUint8(offset + i, s.charCodeAt(i));
  };

  writeAscii(0, "RIFF");
  view.setUint32(4, 36 + dataSize, true);
  writeAscii(8, "WAVE");
  writeAscii(12, "fmt ");
  view.setUint32(16, 16, true); // fmt chunk size
  view.setUint16(20, 1, true); // PCM
  view.setUint16(22, 1, true); // mono
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * 2, true); // byte rate
  view.setUint16(32, 2, true); // block align
  view.setUint16(34, 16, true); // bits per sample
  writeAscii(36, "data");
  view.setUint32(40, dataSize, true);

  let offset = 44;
  for (const chunk of chunks) {
    for (let i = 0; i < chunk.length; i++) {
      const s = Math.max(-1, Math.min(1, chunk[i]));
      view.setInt16(offset, s < 0 ? s * 0x8000 : s * 0x7fff, true);
      offset += 2;
    }
  }
  return new Blob([buf], { type: "audio/wav" });
}

