private async endTurnBatch(): Promise<void> {
  const chunks = this.turnChunks;
  this.resetTurn();
  if (chunks.length === 0) return;
  this.emitting = true;
  this.opts.onPartial("… transcribing");
  try {
    const backend = this.opts.sttBackend;
    const res = await fetch(`/api/stt${backend ? `?backend=${encodeURIComponent(backend)}` : ""}`, {
      method: "POST",
      headers: { "Content-Type": "audio/wav" },
      body: encodeWavPcm16(chunks, SAMPLE_RATE),
    });
    if (!res.ok) throw new Error(`stt ${res.status}`);
    const json = (await res.json()) as { text?: string };
    const text = json.text?.trim();
    if (!this.closed && text) this.opts.onFinal(text);
  } catch (err) {
    if (!this.closed) {
      this.opts.onError?.(
        `batch STT failed (${err instanceof Error ? err.message : "network error"})`,
      );
    }
  } finally {
    this.emitting = false;
  }
}

