() => {
  const active = () => document.querySelector(".tb-nav-item.on")?.textContent?.trim();
  const press = (key) =>
    window.dispatchEvent(new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true }));
  const results = {};
  return new Promise((resolve) => {
    setTimeout(() => {
      press("p");
      setTimeout(() => {
        results.p = active();
        press("v");
        setTimeout(() => {
          results.v = active();
          press("s");
          setTimeout(() => {
            results.s = active();
            press("c");
            setTimeout(() => {
              results.c = active();
              // modifier + key must NOT navigate
              press("p");
              window.dispatchEvent(new KeyboardEvent("keydown", { key: "s", metaKey: true, bubbles: true, cancelable: true }));
              setTimeout(() => {
                results.metaS_after_p = active();
                resolve(results);
              }, 150);
            }, 150);
          }, 150);
        }, 150);
      }, 150);
    }, 1200); // let HMR settle
  });
}

() => {
